  tags?: string[];
  makePublic?: boolean;
}

interface FileUploadResult {
  success: boolean;
  filePath: string;
  publicUrl?: string;
  size: number;
  contentType: string;
  error?: string;
}

interface FunctionResult {
  success: boolean;
  data?: any;
  error?: string;
  code?: string;
  details?: any;
}

interface UserData {
  uid: string;
  email: string;
