}

interface PaginatedResult<T> {
  data: T[];
  hasNext: boolean;
  nextCursor: string | null;
}

interface TransactionOperation {
  type: 'set' | 'update' | 'delete';
  collection: string;
  docId: string;
  data?: any;
  options?: { merge?: boolean };
}

interface CompositeQuery {
