### Keyboard Navigation Implementation

**Hook** (`hooks/useKeyboardNavigation.ts`):

```typescript
import { useEffect, useRef } from 'react';

interface KeyboardNavigationOptions {
  onEscape?: () => void;
  onEnter?: () => void;
  trapFocus?: boolean;
  enableArrowKeys?: boolean;
}

export function useKeyboardNavigation<T extends HTMLElement>(
  options: KeyboardNavigationOptions = {}
) {
  const elementRef = useRef<T>(null);

  useEffect(() => {
    const element = elementRef.current;
    if (!element) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      // Escape key handling
      if (e.key === 'Escape' && options.onEscape) {
        options.onEscape();
        return;
      }

      // Enter key handling
      if (e.key === 'Enter' && options.onEnter) {
        options.onEnter();
        return;
      }

      // Focus trap (Tab key)
      if (e.key === 'Tab' && options.trapFocus) {
        const focusableElements = element.querySelectorAll<HTMLElement>(
          'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
        );

        if (focusableElements.length === 0) return;

        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];

        if (e.shiftKey) {
          // Shift+Tab: going backwards
          if (document.activeElement === firstElement) {
            lastElement.focus();
            e.preventDefault();
          }
        } else {
          // Tab: going forwards
          if (document.activeElement === lastElement) {
            firstElement.focus();
            e.preventDefault();
          }
        }
      }

      // Arrow key navigation
      if (options.enableArrowKeys && ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
        const focusableElements = Array.from(
          element.querySelectorAll<HTMLElement>(
            '[role="menuitem"], [role="option"], [role="tab"]'
          )
        );

        if (focusableElements.length === 0) return;

        const currentIndex = focusableElements.indexOf(document.activeElement as HTMLElement);
        let nextIndex = currentIndex;

        if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
          nextIndex = (currentIndex + 1) % focusableElements.length;
        } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
          nextIndex = (currentIndex - 1 + focusableElements.length) % focusableElements.length;
        }

        focusableElements[nextIndex].focus();
        e.preventDefault();
      }
    };

    element.addEventListener('keydown', handleKeyDown);
    return () => element.removeEventListener('keydown', handleKeyDown);
  }, [options]);

  return elementRef;
}
```

**Usage Example** (Modal component):

```typescript
import { useKeyboardNavigation } from '../../hooks/useKeyboardNavigation';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  children: React.ReactNode;
}

export function Modal({ isOpen, onClose, children }: ModalProps) {
  const modalRef = useKeyboardNavigation<HTMLDivElement>({
    onEscape: onClose,
    trapFocus: true
  });

  useEffect(() => {
    if (isOpen && modalRef.current) {
      const firstFocusable = modalRef.current.querySelector<HTMLElement>(
        'button, [href], input'
      );
      firstFocusable?.focus();
    }
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div
      ref={modalRef}
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-title"
      className="modal-overlay"
    >
      <div className="modal-content">
        {children}
      </div>
    </div>
  );
}
```

### ARIA Implementation Examples

**FormField with Complete ARIA** (`components/molecules/FormField/FormField.tsx`):

```typescript
import { useId, forwardRef } from 'react';
import { Input } from '../../atoms/Input';
import { Label } from '../../atoms/Label';

interface FormFieldProps {
  label: string;
  error?: string;
  hint?: string;
  required?: boolean;
  disabled?: boolean;
  type?: string;
  value?: string;
  onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void;
}

export const FormField = forwardRef<HTMLInputElement, FormFieldProps>(
  ({ label, error, hint, required, disabled, ...inputProps }, ref) => {
    const inputId = useId();
    const errorId = `${inputId}-error`;
    const hintId = `${inputId}-hint`;

    return (
      <div className="form-field">
        <Label htmlFor={inputId}>
          {label}
          {required && (
            <span className="required-indicator" aria-label="required field">
              *
            </span>
          )}
        </Label>

        {hint && !error && (
          <p id={hintId} className="hint-text">
            {hint}
          </p>
        )}

        <Input
          ref={ref}
          id={inputId}
          aria-invalid={!!error}
          aria-describedby={
            error ? errorId : hint ? hintId : undefined
          }
          aria-required={required}
          disabled={disabled}
          {...inputProps}
        />

        {error && (
          <p id={errorId} role="alert" className="error-text">
            {error}
          </p>
        )}
      </div>
    );
  }
);

FormField.displayName = 'FormField';
```

