## Example 4: Configuration File Manager (Rust TOML)

```rust
// Cargo.toml
[dependencies]
clap = { version = "4.5", features = ["derive"] }
toml = "0.8"
serde = { version = "1.0", features = ["derive"] }
anyhow = "1.0"

// src/main.rs
use clap::{Parser, Subcommand};
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::PathBuf;
use anyhow::Result;

#[derive(Parser)]
struct Args {
    #[command(subcommand)]
    command: Commands,

    #[arg(global = true, short, long)]
    config: PathBuf,
}

#[derive(Subcommand)]
enum Commands {
    Show,
    Set { key: String, value: String },
    Get { key: String },
    Validate,
}

#[derive(Debug, Serialize, Deserialize)]
struct AppConfig {
    app: AppSection,
    database: DatabaseSection,
}

#[derive(Debug, Serialize, Deserialize)]
struct AppSection {
    name: String,
    version: String,
    debug: bool,
}

#[derive(Debug, Serialize, Deserialize)]
struct DatabaseSection {
    host: String,
    port: u16,
    username: String,
}

fn main() -> Result<()> {
    let args = Args::parse();

    match args.command {
        Commands::Show => {
            let config = load_config(&args.config)?;
            println!("{}", toml::to_string_pretty(&config)?);
        }
        Commands::Get { key } => {
            let content = fs::read_to_string(&args.config)?;
            let config: toml::Table = toml::from_str(&content)?;
            if let Some(value) = config.get(&key) {
                println!("{} = {}", key, value);
            } else {
                eprintln!("Key not found: {}", key);
            }
        }
        Commands::Set { key, value } => {
            let mut config_content = fs::read_to_string(&args.config)?;
            let mut config: toml::Table = toml::from_str(&config_content)?;
            config.insert(key.clone(), value.parse()?);
            fs::write(&args.config, toml::to_string_pretty(&config)?)?;
            println!("Updated: {} = {}", key, value);
        }
        Commands::Validate => {
            let _config = load_config(&args.config)?;
            println!("Configuration is valid");
        }
    }

    Ok(())
}

fn load_config(path: &PathBuf) -> Result<AppConfig> {
    let content = fs::read_to_string(path)?;
    Ok(toml::from_str(&content)?)
}
