## Example 7: Performance Optimization Patterns

```typescript
// optimized-list.tsx
import React, { useCallback, useMemo } from 'react';
import { FlatList, View, Text, Image, StyleSheet } from 'react-native';

interface ListItem {
  id: string;
  title: string;
  imageUrl: string;
  description: string;
}

interface OptimizedListProps {
  data: ListItem[];
  onEndReached: () => void;
  isLoading: boolean;
}

const ListItemComponent = React.memo<{ item: ListItem }>(({ item }) => (
  <View style={styles.item}>
    <Image 
      source={{ uri: item.imageUrl }} 
      style={styles.image}
      cache="force-cache"
    />
    <View style={styles.content}>
      <Text style={styles.title}>{item.title}</Text>
      <Text style={styles.description}>{item.description}</Text>
    </View>
  </View>
));

export const OptimizedList: React.FC<OptimizedListProps> = ({
  data,
  onEndReached,
  isLoading,
}) => {
  const renderItem = useCallback(
    ({ item }: { item: ListItem }) => <ListItemComponent item={item} />,
    []
  );

  const keyExtractor = useCallback((item: ListItem) => item.id, []);

  // Memoize the list to prevent unnecessary re-renders
  const memoizedData = useMemo(() => data, [data]);

  return (
    <FlatList
      data={memoizedData}
      renderItem={renderItem}
      keyExtractor={keyExtractor}
      // Performance optimizations
      removeClippedSubviews={true}
      maxToRenderPerBatch={20}
      updateCellsBatchingPeriod={50}
      initialNumToRender={20}
      windowSize={10}
      scrollEventThrottle={16}
      // Handle pagination
      onEndReached={() => !isLoading && onEndReached()}
      onEndReachedThreshold={0.5}
      // Loading indicator
      ListFooterComponent={
        isLoading ? (
          <View style={styles.loader}>
            <Text>Loading...</Text>
          </View>
        ) : null
      }
    />
  );
};

const styles = StyleSheet.create({
  item: {
    flexDirection: 'row',
    padding: 12,
    borderBottomWidth: 1,
    borderBottomColor: '#ddd',
  },
  image: {
