### Flutter Performance Optimization

```dart
// Flutter performance optimization techniques
import 'package:flutter/foundation.dart';

class OptimizedListView extends StatefulWidget {
  final List<Item> items;
  final Widget Function(BuildContext, Item) itemBuilder;

  const OptimizedListView({
    Key? key,
    required this.items,
    required this.itemBuilder,
  }) : super(key: key);

  @override
  _OptimizedListViewState createState() => _OptimizedListViewState();
}

class _OptimizedListViewState extends State<OptimizedListView> {
  final ScrollController _scrollController = ScrollController();
  final List<Item> _visibleItems = [];
  bool _isLoading = false;

  @override
  void initState() {
    super.initState();
    _loadMoreItems();
    _scrollController.addListener(_onScroll);
  }

  void _onScroll() {
    if (_scrollController.position.pixels >= 
        _scrollController.position.maxScrollExtent - 200) {
      _loadMoreItems();
    }
  }

  Future<void> _loadMoreItems() async {
    if (_isLoading) return;

    setState(() => _isLoading = true);

    // Simulate async data loading
    await Future.delayed(Duration(milliseconds: 500));

    setState(() {
      _visibleItems.addAll(widget.items);
      _isLoading = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return NotificationListener<ScrollNotification>(
      onNotification: (notification) {
        if (notification is ScrollEndNotification &&
            notification.metrics.extentAfter == 0) {
          _loadMoreItems();
          return true;
        }
        return false;
      },
      child: ListView.builder(
        controller: _scrollController,
        itemCount: _visibleItems.length + (_isLoading ? 1 : 0),
        itemBuilder: (context, index) {
          if (index == _visibleItems.length && _isLoading) {
            return const Center(
              child: CircularProgressIndicator(),
            );
          }

          return widget.itemBuilder(context, _visibleItems[index]);
        },
        cacheExtent: 500.0,
      ),
    );
  }
}

// Image optimization
class OptimizedImage extends StatelessWidget {
  final String imageUrl;
  final double? width;
  final double? height;
  final BoxFit fit;

  const OptimizedImage({
    Key? key,
    required this.imageUrl,
    this.width,
    this.height,
    this.fit = BoxFit.cover,
  }) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Image.network(
      imageUrl,
      width: width,
      height: height,
      fit: fit,
      loadingBuilder: (context, child, loadingProgress) {
        if (loadingProgress == null) return child;
        return Center(
          child: CircularProgressIndicator(
            value: loadingProgress.expectedTotalBytes != null
                ? loadingProgress.cumulativeBytesLoaded /
                    loadingProgress.expectedTotalBytes!
                : null,
          ),
        );
      },
      errorBuilder: (context, error, stackTrace) {
        return Container(
          width: width,
          height: height,
          color: Colors.grey[300],
          child: const Icon(Icons.error),
        );
      },
      cacheWidth: width?.toInt(),
      cacheHeight: height?.toInt(),
    );
  }
}
