## Icon Customization Techniques

### SVG Manipulation and Animation

```typescript
import React, { useState, useEffect } from 'react';

interface AnimatedIconProps {
  icon: React.ComponentType<any>;
  size?: number;
  color?: string;
  animationType?: 'rotate' | 'pulse' | 'bounce' | 'morph';
  duration?: number;
  trigger?: 'hover' | 'load' | 'click';
}

const AnimatedIcon: React.FC<AnimatedIconProps> = ({
  icon: IconComponent,
  size = 24,
  color = 'currentColor',
  animationType = 'pulse',
  duration = 1000,
  trigger = 'hover',
}) => {
  const [isAnimating, setIsAnimating] = useState(false);
  const [key, setKey] = useState(0);

  useEffect(() => {
    if (trigger === 'load') {
      setIsAnimating(true);
      const timer = setTimeout(() => setIsAnimating(false), duration);
      return () => clearTimeout(timer);
    }
  }, [trigger, duration]);

  const animationStyles = {
    rotate: {
      transform: isAnimating ? `rotate(360deg)` : 'rotate(0deg)',
      transition: `transform ${duration}ms linear`,
    },
    pulse: {
      transform: isAnimating ? 'scale(1.2)' : 'scale(1)',
      opacity: isAnimating ? 0.7 : 1,
      transition: `transform ${duration}ms ease-in-out, opacity ${duration}ms ease-in-out`,
    },
    bounce: {
      animation: isAnimating ? `bounce ${duration}ms ease-in-out` : 'none',
    },
    morph: {
      filter: isAnimating ? 'hue-rotate(180deg)' : 'none',
      transition: `filter ${duration}ms ease-in-out`,
    },
  };

  const handleClick = () => {
    if (trigger === 'click') {
      setIsAnimating(true);
      setKey(prev => prev + 1);
      setTimeout(() => setIsAnimating(false), duration);
    }
  };

  const handleMouseEnter = () => {
    if (trigger === 'hover') {
      setIsAnimating(true);
    }
  };

  const handleMouseLeave = () => {
    if (trigger === 'hover') {
      setIsAnimating(false);
    }
  };

  return (
    <span
      key={key}
      style={{
        display: 'inline-block',
        width: size,
        height: size,
        ...animationStyles[animationType],
      }}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onClick={handleClick}
    >
      <IconComponent
        size={size}
        color={color}
        style={{
          width: '100%',
          height: '100%',
        }}
      />
    </span>
  );
};

// CSS animation definitions for bounce
const style = document.createElement('style');
style.textContent = `
  @keyframes bounce {
    0%, 100% {
      transform: translateY(0);
    }
    50% {
      transform: translateY(-10px);
    }
  }
`;
document.head.appendChild(style);
