**Passport.js 0.7.x:**

```typescript
import { Strategy as LocalStrategy } from 'passport-local';
import { Strategy as JwtStrategy, ExtractJwt } from 'passport-jwt';
import bcrypt from 'bcryptjs';
import passport from 'passport';

// 1. Local Strategy (username/password)
passport.use(new LocalStrategy(
  {
    usernameField: 'email',
    passwordField: 'password',
    passReqToCallback: true
  },
  async (req, email, password, done) => {
    try {
      const user = await db.users.findByEmail(email);

      if (!user) {
        return done(null, false, { 
          message: 'Invalid credentials' 
        });
      }

      // Check if account is locked
      if (user.loginAttempts >= 5 && 
          Date.now() < user.lockUntil) {
        return done(null, false, { 
          message: 'Account locked. Try again later.' 
        });
      }

      const isPasswordValid = await bcrypt.compare(
        password,
        user.passwordHash
      );

      if (!isPasswordValid) {
        // Increment failed attempts
        await db.users.update(user.id, {
          loginAttempts: (user.loginAttempts || 0) + 1,
          lockUntil: user.loginAttempts >= 4 
            ? new Date(Date.now() + 30 * 60000) // 30 min lock
            : undefined
        });

        return done(null, false, { 
          message: 'Invalid credentials' 
        });
      }

      // Reset lock on successful login
      if (user.loginAttempts > 0) {
        await db.users.update(user.id, {
          loginAttempts: 0,
          lockUntil: null
        });
      }

      return done(null, user);
    } catch (err) {
      return done(err);
    }
  }
));

// 2. JWT Strategy
passport.use(new JwtStrategy(
  {
    jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
    secretOrKey: process.env.JWT_SECRET,
    algorithms: ['HS256']
  },
  async (jwtPayload, done) => {
    try {
      const user = await db.users.findById(jwtPayload.id);

      if (!user) {
        return done(null, false);
      }

      // Check if token is blacklisted (logout)
      const isBlacklisted = await redis.get(
        `jwt:blacklist:${jwtPayload.jti}`
      );

      if (isBlacklisted) {
        return done(null, false);
      }

      return done(null, user, jwtPayload);
    } catch (err) {
      return done(err);
    }
  }
));

// 3. Serialization
passport.serializeUser((user, done) => {
  done(null, user.id);
});

passport.deserializeUser(async (id, done) => {
  try {
    const user = await db.users.findById(id);
    done(null, user);
  } catch (err) {
    done(err);
  }
});

// 4. Express middleware
app.post('/login', 
  passport.authenticate('local', { session: false }),
  (req, res) => {
    const token = jwt.sign(
      { id: req.user.id, jti: uuid() },
      process.env.JWT_SECRET,
      { expiresIn: '7d' }
    );

    res.json({ token, user: req.user });
  }
);

// Protected route
app.get('/profile',
  passport.authenticate('jwt', { session: false }),
  (req, res) => {
    res.json(req.user);
  }
);
