## Example 4: Passport.js Local + JWT Strategy

```typescript
// strategies/passport-config.ts
import { Strategy as LocalStrategy } from 'passport-local';
import { Strategy as JwtStrategy, ExtractJwt } from 'passport-jwt';
import bcrypt from 'bcryptjs';
import passport from 'passport';

export function setupPassport() {
  // 1. Local Strategy (login)
  passport.use(new LocalStrategy(
    {
      usernameField: 'email',
      passwordField: 'password'
    },
    async (email, password, done) => {
      try {
        const user = await db.users.findByEmail(email);

        if (!user) {
          return done(null, false, { message: 'User not found' });
        }

        // Check account lock
        if (user.lockedUntil && user.lockedUntil > new Date()) {
          return done(null, false, { message: 'Account locked' });
        }

        // Verify password
        const isValid = await bcrypt.compare(password, user.passwordHash);

        if (!isValid) {
          // Increment failed attempts
          const attempts = (user.loginAttempts || 0) + 1;
          const lockUntil = attempts >= 5 
            ? new Date(Date.now() + 30 * 60000)
            : null;

          await db.users.update(user.id, {
            loginAttempts: attempts,
            lockedUntil: lockUntil
          });

          return done(null, false, { message: 'Invalid password' });
        }

        // Reset attempts on success
        await db.users.update(user.id, {
          loginAttempts: 0,
          lockedUntil: null
        });

        return done(null, user);
      } catch (err) {
        return done(err);
      }
    }
  ));

  // 2. JWT Strategy (verification)
  passport.use(new JwtStrategy(
    {
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      secretOrKey: process.env.JWT_SECRET,
      algorithms: ['HS256']
    },
    async (payload, done) => {
      try {
        // Check token blacklist
        const isBlacklisted = await redis.get(`jwt:blacklist:${payload.jti}`);
        if (isBlacklisted) {
          return done(null, false);
        }

        const user = await db.users.findById(payload.id);
        if (!user) return done(null, false);

        return done(null, user, payload);
      } catch (err) {
        return done(err);
      }
    }
  ));

  // 3. Serialization
  passport.serializeUser((user, done) => {
    done(null, user.id);
  });

  passport.deserializeUser(async (id, done) => {
    try {
      const user = await db.users.findById(id);
      done(null, user);
    } catch (err) {
      done(err);
    }
  });
}

// Usage in routes
app.post('/login', passport.authenticate('local'), (req, res) => {
  const token = jwt.sign(
    { id: req.user.id, jti: uuid() },
    process.env.JWT_SECRET,
    { expiresIn: '7d' }
  );

  res.json({ token });
});

app.post('/logout', (req, res) => {
  // Add token to blacklist
  redis.setex(`jwt:blacklist:${req.user.jti}`, 604800, '1'); // 7 days
  res.json({ message: 'Logged out' });
});

app.get('/profile', 
  passport.authenticate('jwt'),
  (req, res) => {
    res.json(req.user);
  }
);
