### references/endpoint-types-pattern.md
# Endpoint Types Pattern

Structure for `endpoint-types.ts` - TypeScript type definitions for all API endpoints.

## File Organization

```typescript
/**
 * Type definitions for all API endpoints
 * Organized by domain/feature category
 */

// ==========================================
// COMMON TYPES (reusable across domains)
// ==========================================

export interface ApiErrorResponse {
  type?: string;
  title?: string;
  status?: number;
  detail?: string;
  instance?: string;
  [key: string]: any;
}

// ==========================================
// DOMAIN - Response Types
// ==========================================

export interface EntityListItem {
  id: string;
  name: string;
  // ... list view fields
}

export interface EntityDetail {
  id: string;
  name: string;
  // ... full entity fields
}

// ==========================================
// REQUEST BODY DTOs
// ==========================================

export interface CreateEntityDto {
  name: string;
  // ... required creation fields
}

export interface UpdateEntityDto extends CreateEntityDto {
  // Optional: add update-specific fields
}

// ==========================================
// ENDPOINT PARAMETER TYPES
// ==========================================

export interface EndpointParams {
  domain: {
    list: { categoryId: string }; // Required params
    get: { id: string };
    create: void; // No params
    update: { id: string };
    delete: { id: string };
  };
}

// ==========================================
// ENDPOINT RESPONSE TYPES
// ==========================================

export interface EndpointResponses {
  domain: {
    list: EntityListItem[];
    get: EntityDetail;
    create: EntityDetail;
    update: EntityDetail;
    delete: void;
  };
}

// ==========================================
// ENDPOINT REQUEST BODY TYPES
// ==========================================

export interface EndpointBodies {
  domain: {
    create: CreateEntityDto;
    update: UpdateEntityDto;
  };
}

// ==========================================
// UTILITY TYPES
// ==========================================

export type ApiResponse<
  Category extends keyof EndpointResponses,
  Operation extends keyof EndpointResponses[Category]
> = EndpointResponses[Category][Operation];

export type ApiRequestBody<
  Category extends keyof EndpointBodies,
  Operation extends keyof EndpointBodies[Category]
> = EndpointBodies[Category][Operation];

export type ApiParams<
  Category extends keyof EndpointParams,
  Operation extends keyof EndpointParams[Category]
> = EndpointParams[Category][Operation];
```

## Naming Conventions

### Response Types
- **List items**: `{Entity}ListItem` - Lightweight for lists
- **Details**: `{Entity}Detail` or just `{Entity}` - Full object
- **Settings**: `{Entity}Settings` - Configuration objects

### DTOs (Data Transfer Objects)
- **Create**: `Create{Entity}Dto`
- **Update**: `Update{Entity}Dto`
- **Custom**: `{Action}{Entity}Dto` (e.g., `AddUserToGroupsDto`)

### Structure Interfaces
- **Params**: `EndpointParams[category][operation]`
- **Responses**: `EndpointResponses[category][operation]`
- **Bodies**: `EndpointBodies[category][operation]`

## Type Organization Rules

1. **Group by domain** - Keep related types together
2. **Common first** - Shared types at top
3. **Response before DTOs** - Data models before mutations
4. **Three interfaces** - Params, Responses, Bodies
5. **Utility last** - Helper types at bottom

## Examples

### Simple CRUD Domain

```typescript
// Responses
export interface Product {
  id: string;
  name: string;
  price: number;
  sku: string;
}

// DTOs
export interface CreateProductDto {
  name: string;
  price: number;
  sku: string;
}

export interface UpdateProductDto extends CreateProductDto {}

// Params
products: {
  list: void;
  get: { id: string };
  create: void;
  update: { id: string };
  delete: { id: string };
}

// Responses
products: {
  list: Product[];
  get: Product;
  create: Product;
  update: Product;
  delete: void;
}

// Bodies
products: {
  create: CreateProductDto;
  update: UpdateProductDto;
}
```

### Nested/Scoped Domain

```typescript
// Params for nested resources
categoryProducts: {
  list: { categoryId: string };
  create: { categoryId: string };
  get: { categoryId: string; productId: string };
  update: { categoryId: string; productId: string };
  delete: { categoryId: string; productId: string };
}
```

### Multiple Variations

```typescript
// When API has alternative endpoints
settings: {
  get: { instanceId: string };      // /instances/{id}/settings
  getAlt: void;                      // /settings (uses session)
  update: { instanceId: string };
  updateAlt: void;
}
```

## Common Patterns

### Pagination Params
```typescript
list: { page?: number; limit?: number; };
```

### Search/Filter Params
```typescript
search: { query: string; filters?: Record<string, any> };
```

### Batch Operations
```typescript
batchCreate: void;  // Body contains array
```

### Optional Fields in DTOs
```typescript
export interface UpdateUserDto {
  email?: string;
  firstName?: string;
  lastName?: string;
}
```

## Integration with Other Files

Types flow through the system:
1. Define in `endpoint-types.ts`
2. Reference in `endpoints.ts` (implicitly via params)
3. Import in `protected-endpoints.ts` for wrappers
4. Use in application code via `api.*` calls

### references/endpoints-pattern.md
# Endpoints Pattern

Structure for `endpoints.ts` - Centralized API endpoint URL definitions.

## File Structure

```typescript
/**
 * Centralized API Endpoints Configuration
 *
 * All API endpoint URLs defined in one place.
 * Organized by feature/domain for easy maintenance.
 */

// Base URLs from environment variables
const API_BASE = process.env.INSTANCE_API_URL || '';
const NEXT_API_BASE = ''; // Empty for relative Next.js routes

/**
 * API Endpoints organized by feature/domain
 */
export const API_ENDPOINTS = {
  // ==========================================
  // DOMAIN NAME (matches endpoint-types.ts)
  // ==========================================
  domain: {
    // GET /api/domains
    list: () => `${API_BASE}/api/domains`,

    // GET /api/domains/:id
    get: (id: string) => `${API_BASE}/api/domains/${id}`,

    // POST /api/domains
    create: () => `${API_BASE}/api/domains`,

    // PUT /api/domains/:id
    update: (id: string) => `${API_BASE}/api/domains/${id}`,

    // DELETE /api/domains/:id
    delete: (id: string) => `${API_BASE}/api/domains/${id}`,
  },

  // ==========================================
  // NESTED RESOURCES
  // ==========================================
  categoryProducts: {
    // GET /api/categories/:categoryId/products
    list: (categoryId: string) =>
      `${API_BASE}/api/categories/${categoryId}/products`,

    // POST /api/categories/:categoryId/products
    create: (categoryId: string) =>
      `${API_BASE}/api/categories/${categoryId}/products`,

    // GET /api/categories/:categoryId/products/:productId
    get: (categoryId: string, productId: string) =>
      `${API_BASE}/api/categories/${categoryId}/products/${productId}`,

    // PUT /api/categories/:categoryId/products/:productId
    update: (categoryId: string, productId: string) =>
      `${API_BASE}/api/categories/${categoryId}/products/${productId}`,
  },
};
```

## Organization Rules

### Domain Grouping
Match structure in `endpoint-types.ts`:
```typescript
// endpoint-types.ts has:
export interface EndpointParams {
  products: { ... }
}

// endpoints.ts must have:
export const API_ENDPOINTS = {
  products: { ... }
}
```

### Function Signatures
All endpoint functions:
- Accept parameters that appear in URL or query string
- Return complete URL string
- Use arrow function syntax

```typescript
// Path parameters
get: (id: string) => `${API_BASE}/api/items/${id}`

// Multiple path parameters
getVersion: (id: string, version: number) =>
  `${API_BASE}/api/items/${id}/versions/${version}`

// Query parameters (handled by client, not in URL builder)
// Don't include query params in these functions
```

### Base URL Selection

```typescript
// External API (environment variable)
const API_BASE = process.env.INSTANCE_API_URL || 'https://api.example.com';

// Next.js internal routes (relative paths)
const NEXT_API_BASE = '';

// Use in endpoints:
externalApi: {
  list: () => `${API_BASE}/api/resources`
},

internalApi: {
  list: () => `${NEXT_API_BASE}/api/internal/resources`
}
```

## Naming Conventions

### Operation Names
Match CRUD operations:
- `list` - GET collection
- `listAll` - GET all (no pagination)
- `get` - GET single item
- `create` - POST new item
- `update` - PUT/PATCH item
- `delete` - DELETE item
- `{action}` - Custom operation (e.g., `activate`, `archive`)

### Alternative Endpoints
Use suffix when multiple endpoints exist:
```typescript
settings: {
  get: (instanceId: string) => `${API_BASE}/api/settings/${instanceId}`,
  getAlt: () => `${API_BASE}/api/settings`, // Uses session context

  update: (instanceId: string) => `${API_BASE}/api/settings/${instanceId}`,
  updateGeneral: () => `${API_BASE}/api/settings`, // General endpoint
}
```

## Common Patterns

### Resource Collections
```typescript
users: {
  list: () => `${API_BASE}/api/users`,
  get: (id: string) => `${API_BASE}/api/users/${id}`,
  create: () => `${API_BASE}/api/users`,
  update: (id: string) => `${API_BASE}/api/users/${id}`,
  delete: (id: string) => `${API_BASE}/api/users/${id}`,
}
```

### Nested Resources
```typescript
posts: {
  comments: {
    list: (postId: string) => `${API_BASE}/api/posts/${postId}/comments`,
    create: (postId: string) => `${API_BASE}/api/posts/${postId}/comments`,
    get: (postId: string, commentId: string) =>
      `${API_BASE}/api/posts/${postId}/comments/${commentId}`,
  }
}
```

### Scoped Endpoints
```typescript
// Instance-scoped resources
instanceResources: {
  list: (instanceId: string) =>
    `${API_BASE}/api/instances/${instanceId}/resources`,
}

// User-scoped resources
userResources: {
  list: (userId: string) =>
    `${API_BASE}/api/users/${userId}/resources`,
}
```

### Action Endpoints
```typescript
users: {
  // CRUD operations
  get: (id: string) => `${API_BASE}/api/users/${id}`,

  // Custom actions
  activate: (id: string) => `${API_BASE}/api/users/${id}/activate`,
  deactivate: (id: string) => `${API_BASE}/api/users/${id}/deactivate`,
  resetPassword: (id: string) => `${API_BASE}/api/users/${id}/reset-password`,
}
```

### Legacy/Backward Compatible
```typescript
audience: {
  // New API
  list: (instanceId: string) => `${API_BASE}/api/instances/${instanceId}/audiences`,

  // Legacy API (keep for backward compatibility)
  getSavedAudiences: (instanceId: string) =>
    `${API_BASE}/api/instances/${instanceId}/qualificationgroups`,
}
```

