## 2. State Management Strategy

### Local State (useState)

```typescript
// ✅ USE for: Form inputs, UI toggles, temporary state
'use client';

function EditForm({ user }: { user: User }) {
  const [name, setName] = useState(user.name);
  const [isSaving, setIsSaving] = useState(false);

  return (
    <form onSubmit={async (e) => {
      e.preventDefault();
      setIsSaving(true);
      await updateUser({ name });
      setIsSaving(false);
    }}>
      <input value={name} onChange={e => setName(e.target.value)} />
      <button disabled={isSaving}>{isSaving ? 'Saving...' : 'Save'}</button>
    </form>
  );
}
```

### Context API

```typescript
// ✅ USE for: Theme, auth, global app state

// app/providers.tsx
'use client';

import { createContext, useState, ReactNode } from 'react';

type Theme = 'light' | 'dark';

export const ThemeContext = createContext<{
  theme: Theme;
  setTheme: (theme: Theme) => void;
}>({
  theme: 'light',
  setTheme: () => {},
});

export function Providers({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>('light');

  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

// In component
'use client';

import { useContext } from 'react';
import { ThemeContext } from '@/app/providers';

export function ThemeToggle() {
  const { theme, setTheme } = useContext(ThemeContext);

  return (
    <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>
      {theme}
    </button>
  );
}
```

### Server State (Caching & Revalidation)

```typescript
// ✅ USE for: User data, posts, any database content

// app/dashboard/page.tsx
import { cache } from 'react';
import { unstable_cache } from 'next/cache';

// Cache function for 1 hour
const getPosts = unstable_cache(
  async () => {
    return await db.posts.findMany();
  },
  ['posts'],
  { revalidate: 3600 },
);

export default async function Dashboard() {
  const posts = await getPosts();

  return (
    <div>
      {posts.map(post => (
        <article key={post.id}>{post.title}</article>
      ))}
    </div>
  );
}

// Revalidate on demand
export async function deletePost(id: string) {
  'use server';

  await db.posts.delete({ where: { id } });

  // Revalidate cache
  revalidateTag('posts');
  revalidatePath('/dashboard');
}
```

