### API Routes for Client Fetching

```typescript
// When client needs data: Use API Routes

// app/api/users/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

export async function GET(request: NextRequest) {
  try {
    const users = await db.users.findMany();
    return NextResponse.json(users);
  } catch (error) {
    return NextResponse.json(
      { error: 'Failed to fetch users' },
      { status: 500 }
    );
  }
}

// Client component using it
'use client';

import { useAsync } from '@/hooks/use-async';

function UsersList() {
  const { data: users, loading, error } = useAsync(
    () => fetch('/api/users').then(r => r.json()),
    []
  );

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <ul>
      {users.map(user => (
        <li key={user.id}>{user.name}</li>
      ))}
    </ul>
  );
}
```

### Server Actions for Mutations

```typescript
// ✅ BEST - Use Server Actions for all data modifications

'use server';

import { revalidatePath } from 'next/cache';
import { z } from 'zod';

const UpdateUserSchema = z.object({
  id: z.string().uuid(),
  name: z.string().min(1),
  email: z.string().email(),
});

export async function updateUser(input: unknown): Promise<ActionResult<User>> {
  try {
    const data = UpdateUserSchema.parse(input);

    const user = await db.users.update({
      where: { id: data.id },
      data: { name: data.name, email: data.email },
    });

    // Revalidate related pages
    revalidatePath('/users');
    revalidatePath(`/users/${user.id}`);

    return { success: true, data: user };
  } catch (error) {
    if (error instanceof z.ZodError) {
      return {
        success: false,
        data: null,
        error: error.errors[0]?.message || 'Validation failed',
      };
    }

    return {
      success: false,
      data: null,
      error: 'Update failed',
    };
  }
}

// Client usage
'use client';

import { updateUser } from './actions';

export function EditUserForm({ user }: { user: User }) {
  const [formData, setFormData] = useState(user);
  const [isSubmitting, setIsSubmitting] = useState(false);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setIsSubmitting(true);

    const result = await updateUser(formData);

    if (result.success) {
      // Show success
    } else {
      // Show error
      alert(result.error);
    }

    setIsSubmitting(false);
  }

  return (
    <form onSubmit={handleSubmit}>
      {/* form fields */}
    </form>
  );
}
```

