## Server Action Patterns

### Validation Pattern

```typescript
'use server';

import { z } from 'zod';

// 1. Define schema
const InputSchema = z.object({
  email: z.string().email(),
  name: z.string().min(1),
});

// 2. Define types
type Input = z.infer<typeof InputSchema>;
type Success = { id: string; email: string };

// 3. Implement action
export async function myAction(
  input: unknown,
): Promise<ActionResult<Success>> {
  try {
    // 4. Validate
    const validated = InputSchema.parse(input);

    // 5. Process
    const result = await processData(validated);

    // 6. Return success
    return {
      success: true,
      data: result,
    };
  } catch (error) {
    // 7. Handle errors
    if (error instanceof z.ZodError) {
      return {
        success: false,
        data: null,
        error: error.errors[0]?.message || 'Validation failed',
      };
    }

    console.error('[myAction] Error:', error);

    return {
      success: false,
      data: null,
      error: 'Operation failed',
    };
  }
}
```

### Cache Revalidation Pattern

```typescript
'use server';

import { revalidatePath, revalidateTag } from 'next/cache';

export async function updateUser(input: unknown): Promise<ActionResult<User>> {
  try {
    const validated = UserSchema.parse(input);

    // Update database
    const user = await db.users.update(validated);

    // Revalidate by path
    revalidatePath('/users');
    revalidatePath(`/users/${user.id}`);

    // Revalidate by tag
    revalidateTag(`user_${user.id}`);

    return { success: true, data: user };
  } catch (error) {
    // ... error handling
  }
}
```

