// my-component-styles.js
export const styles = `
    :host {
        display: block;
        margin: var(--size-3);
    }

    :host([hidden]) {
        display: none;
    }

    .container {
        padding: var(--size-2);
        background: var(--surface-1);
        border-radius: var(--radius-2);
    }

    button {
        background: var(--brand);
