#### 1.4 Enhanced Auth Service
```typescript
// backend/src/services/authService.ts
import { User, UserRole, UserStatus } from '../entities/User';
import { RefreshToken } from '../entities/RefreshToken';
import { getRepository } from 'typeorm';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import crypto from 'crypto';
import { EmailService } from './emailService';

const MAX_LOGIN_ATTEMPTS = 5;
const LOCK_TIME = 2 * 60 * 60 * 1000; // 2 hours

export class AuthService {
  private userRepository = getRepository(User);
  private refreshTokenRepository = getRepository(RefreshToken);
  private emailService = new EmailService();

  /**
   * Register new user
   */
  async register(data: {
    email: string;
    password: string;
    firstName: string;
    lastName: string;
    role?: UserRole;
  }): Promise<{ user: User; verificationToken: string }> {
    // Check if user exists
    const existingUser = await this.userRepository.findOne({
      where: { email: data.email }
    });

    if (existingUser) {
      throw new Error('Email already registered');
    }

    // Hash password
    const hashedPassword = await bcrypt.hash(data.password, 12);

    // Generate email verification token
    const verificationToken = crypto.randomBytes(32).toString('hex');

    // Create user
    const user = this.userRepository.create({
      email: data.email,
      password: hashedPassword,
      firstName: data.firstName,
      lastName: data.lastName,
      role: data.role || UserRole.STUDENT,
      status: UserStatus.PENDING_VERIFICATION,
      emailVerificationToken: verificationToken
    });

    await this.userRepository.save(user);

    // Send verification email
    await this.emailService.sendVerificationEmail(user.email, verificationToken);

    return { user, verificationToken };
  }

  /**
   * Verify email
   */
  async verifyEmail(token: string): Promise<User> {
    const user = await this.userRepository.findOne({
      where: { emailVerificationToken: token }
    });

    if (!user) {
      throw new Error('Invalid verification token');
    }

    user.emailVerifiedAt = new Date();
    user.emailVerificationToken = null;
    user.status = UserStatus.ACTIVE;

    await this.userRepository.save(user);

    return user;
  }

  /**
   * Login user
   */
  async login(
    email: string,
    password: string,
    ipAddress: string,
    rememberMe: boolean = false
  ): Promise<{ user: User; accessToken: string; refreshToken: string }> {
    // Find user with password
    const user = await this.userRepository
      .createQueryBuilder('user')
      .addSelect('user.password')
      .where('user.email = :email', { email })
      .getOne();

    if (!user) {
      throw new Error('Invalid credentials');
    }

    // Check if account is locked
    if (user.isLocked) {
      throw new Error(
        `Account locked due to too many failed login attempts. Try again later.`
      );
    }

    // Check if email is verified
    if (!user.isVerified) {
      throw new Error('Please verify your email before logging in');
    }

    // Check if account is active
    if (user.status !== UserStatus.ACTIVE) {
      throw new Error('Account is not active');
    }

    // Verify password
    const isPasswordValid = await bcrypt.compare(password, user.password);

    if (!isPasswordValid) {
      // Increment login attempts
      await this.handleFailedLogin(user);
      throw new Error('Invalid credentials');
    }

    // Reset login attempts on successful login
    user.loginAttempts = 0;
    user.lockUntil = null;
    user.lastLoginAt = new Date();
    user.lastLoginIp = ipAddress;
    await this.userRepository.save(user);

    // Generate tokens
    const accessToken = this.generateAccessToken(user);
    const refreshToken = await this.generateRefreshToken(user, ipAddress, rememberMe);

    return { user, accessToken, refreshToken: refreshToken.token };
  }

  /**
   * Handle failed login attempt
   */
  private async handleFailedLogin(user: User): Promise<void> {
    user.loginAttempts += 1;

    if (user.loginAttempts >= MAX_LOGIN_ATTEMPTS) {
      user.lockUntil = new Date(Date.now() + LOCK_TIME);
    }

    await this.userRepository.save(user);
  }

  /**
   * Generate access token (JWT)
   */
  private generateAccessToken(user: User): string {
    const payload = {
      sub: user.id,
      email: user.email,
      role: user.role,
      permissions: user.permissions?.map(p => `${p.resource}:${p.action}`)
    };

    return jwt.sign(payload, process.env.JWT_SECRET, {
      expiresIn: '15m' // Short-lived access token
    });
  }

  /**
   * Generate refresh token
   */
  private async generateRefreshToken(
    user: User,
    ipAddress: string,
    rememberMe: boolean
  ): Promise<RefreshToken> {
    const token = crypto.randomBytes(40).toString('hex');
    const expiresAt = new Date();

    // Remember me: 30 days, otherwise 7 days
    expiresAt.setDate(expiresAt.getDate() + (rememberMe ? 30 : 7));

    const refreshToken = this.refreshTokenRepository.create({
      token,
      user,
      expiresAt,
      createdByIp: ipAddress
    });

    await this.refreshTokenRepository.save(refreshToken);

    return refreshToken;
  }

  /**
   * Refresh access token
   */
  async refreshToken(
    token: string,
    ipAddress: string
  ): Promise<{ accessToken: string; refreshToken: string }> {
    const refreshToken = await this.refreshTokenRepository.findOne({
      where: { token },
      relations: ['user', 'user.permissions']
    });

    if (!refreshToken || !refreshToken.isActive) {
      throw new Error('Invalid refresh token');
    }

    // Generate new tokens
    const newRefreshToken = await this.generateRefreshToken(
      refreshToken.user,
      ipAddress,
      false
    );

    // Revoke old token
    refreshToken.revokedAt = new Date();
    refreshToken.revokedByIp = ipAddress;
    refreshToken.replacedByToken = newRefreshToken.token;
    await this.refreshTokenRepository.save(refreshToken);

    const accessToken = this.generateAccessToken(refreshToken.user);

    return { accessToken, refreshToken: newRefreshToken.token };
  }

  /**
   * Logout (revoke refresh token)
   */
  async logout(token: string, ipAddress: string): Promise<void> {
    const refreshToken = await this.refreshTokenRepository.findOne({
      where: { token }
    });

    if (refreshToken && refreshToken.isActive) {
      refreshToken.revokedAt = new Date();
      refreshToken.revokedByIp = ipAddress;
      await this.refreshTokenRepository.save(refreshToken);
    }
  }

  /**
   * Request password reset
   */
  async requestPasswordReset(email: string): Promise<void> {
    const user = await this.userRepository.findOne({ where: { email } });

    if (!user) {
      // Don't reveal if email exists
      return;
    }

    // Generate reset token
    const resetToken = crypto.randomBytes(32).toString('hex');
    const resetExpires = new Date();
    resetExpires.setHours(resetExpires.getHours() + 1); // 1 hour expiry

    user.passwordResetToken = resetToken;
    user.passwordResetExpires = resetExpires;
    await this.userRepository.save(user);

    // Send reset email
    await this.emailService.sendPasswordResetEmail(email, resetToken);
  }

  /**
   * Reset password
   */
  async resetPassword(token: string, newPassword: string): Promise<void> {
    const user = await this.userRepository.findOne({
      where: { passwordResetToken: token }
    });

    if (!user) {
      throw new Error('Invalid or expired reset token');
    }

    if (!user.passwordResetExpires || user.passwordResetExpires < new Date()) {
      throw new Error('Reset token has expired');
    }

    // Hash new password
    const hashedPassword = await bcrypt.hash(newPassword, 12);

    user.password = hashedPassword;
    user.passwordResetToken = null;
    user.passwordResetExpires = null;
    user.loginAttempts = 0;
    user.lockUntil = null;

    await this.userRepository.save(user);

    // Send confirmation email
    await this.emailService.sendPasswordChangedEmail(user.email);
  }

  /**
   * Change password (authenticated user)
   */
  async changePassword(
    userId: number,
    currentPassword: string,
    newPassword: string
  ): Promise<void> {
    const user = await this.userRepository
      .createQueryBuilder('user')
      .addSelect('user.password')
      .where('user.id = :userId', { userId })
      .getOne();

    if (!user) {
      throw new Error('User not found');
    }

    // Verify current password
    const isValid = await bcrypt.compare(currentPassword, user.password);

    if (!isValid) {
      throw new Error('Current password is incorrect');
    }

    // Hash and save new password
    user.password = await bcrypt.hash(newPassword, 12);
    await this.userRepository.save(user);

    // Send confirmation email
    await this.emailService.sendPasswordChangedEmail(user.email);
  }

  /**
   * OAuth login (Google, GitHub, etc.)
   */
  async oauthLogin(
    provider: 'google' | 'github',
    profile: {
      id: string;
      email: string;
      firstName: string;
      lastName: string;
      avatarUrl?: string;
    },
    ipAddress: string
  ): Promise<{ user: User; accessToken: string; refreshToken: string }> {
    const providerIdField = provider === 'google' ? 'googleId' : 'githubId';

    // Find user by provider ID or email
    let user = await this.userRepository.findOne({
      where: [
        { [providerIdField]: profile.id },
        { email: profile.email }
      ]
    });

    if (user) {
      // Link provider if not already linked
      if (!user[providerIdField]) {
        user[providerIdField] = profile.id;
        await this.userRepository.save(user);
      }
    } else {
      // Create new user from OAuth profile
      user = this.userRepository.create({
        email: profile.email,
        firstName: profile.firstName,
        lastName: profile.lastName,
        avatarUrl: profile.avatarUrl,
        [providerIdField]: profile.id,
        status: UserStatus.ACTIVE,
        emailVerifiedAt: new Date(), // OAuth emails are pre-verified
        password: await bcrypt.hash(crypto.randomBytes(32).toString('hex'), 12) // Random password
      });

      await this.userRepository.save(user);
    }

    // Update login info
    user.lastLoginAt = new Date();
    user.lastLoginIp = ipAddress;
    await this.userRepository.save(user);

    // Generate tokens
    const accessToken = this.generateAccessToken(user);
    const refreshToken = await this.generateRefreshToken(user, ipAddress, false);

    return { user, accessToken, refreshToken: refreshToken.token };
  }

  /**
   * Get user by ID
   */
  async getUserById(id: number): Promise<User> {
    const user = await this.userRepository.findOne({
      where: { id },
      relations: ['permissions']
    });

    if (!user) {
      throw new Error('User not found');
    }

    return user;
  }

  /**
   * Update user profile
   */
  async updateProfile(
    userId: number,
    data: {
      firstName?: string;
      lastName?: string;
      avatarUrl?: string;
      preferences?: Record<string, any>;
    }
  ): Promise<User> {
    const user = await this.getUserById(userId);

    Object.assign(user, data);

    await this.userRepository.save(user);

    return user;
  }
