# Vercel AI SDK v5

Production patterns for AI chatbots with persistence, generative UI, and streaming.

## Quick Reference

| Need | Reference |
|------|-----------|
| Database schema & persistence | `references/persistence.md` |
| Tools & generative UI | `references/tools-and-generative-ui.md` |
| Custom data streaming | `references/streaming.md` |
| Type definitions | `references/types.md` |
| Anthropic + reasoning | `references/anthropic-config.md` |
| Working examples | `cookbook/` directory |

## Core Architecture

### Message Flow
```
Client (useChat) → API Route (streamText) → DB (Drizzle)
     ↑                    ↓
     └── UIMessageStream ←┘
```

### Key Imports
```typescript
// Core
import { streamText, convertToModelMessages, UIMessage } from 'ai'
import { createUIMessageStream, createUIMessageStreamResponse } from 'ai'

// Client
import { useChat } from '@ai-sdk/react'
import { DefaultChatTransport } from 'ai'

// Provider
import { anthropic } from '@ai-sdk/anthropic'
```

## Decision Tree

### Streaming Response Type
- Simple text streaming → `streamText().toUIMessageStreamResponse()`
- Need custom data parts → `createUIMessageStream()` + `writer.write()`
- Need both → `createUIMessageStream()` + `writer.merge(result.toUIMessageStream())`

### Tool Execution Location
- Has server-side data/secrets → Server tool with `execute`
- Needs client confirmation → Client tool (no execute) + `addToolOutput`
- Auto-runs on client → Client tool + `onToolCall` handler

### Data Attachment
- Message-level info (tokens, model, timestamps) → `messageMetadata`
- Dynamic content in message → Data parts with `writer.write()`
- Temporary status (not persisted) → Transient data parts

## Naming Convention

This skill uses `agents` instead of `chats` for all database tables, routes, and methods:
- Table: `agents` (not `chats`)
- Foreign keys: `agentId` (not `chatId`)
- Actions: `createAgent()`, `loadAgent()`, `deleteAgent()`

## File Organization

Follow feature-based architecture:
```
features/
└── agents/
    ├── data/
    │   └── get-agent.ts
    ├── actions/
    │   └── create-agent.ts
    ├── types/
    │   └── message.ts
    └── components/
        ├── server/
        │   └── agent-messages.tsx
        └── client/
            └── chat-input.tsx

db/
├── schema.ts      # Table definitions
├── relations.ts   # Drizzle relations
└── actions.ts     # DB operations (upsert, load, delete)
```

## Essential Patterns

### 1. Send Only Last Message
```typescript
// Client
transport: new DefaultChatTransport({
  api: '/api/agent',
  prepareSendMessagesRequest: ({ messages, id }) => ({
    body: { message: messages.at(-1), agentId: id }
  })
})

// Server: Load history, append new message
const previous = await loadAgent(agentId)
const messages = [...previous, message]
```

### 2. Persist on Finish
```typescript
return result.toUIMessageStreamResponse({
  originalMessages: messages,
  onFinish: async ({ messages }) => {
    await upsertMessages({ agentId, messages })
  }
})
```

### 3. Handle Disconnects
```typescript
const result = streamText({ ... })
result.consumeStream() // No await - ensures completion even on disconnect
return result.toUIMessageStreamResponse({ ... })
```

### 4. Type-Safe Tools
```typescript
const tools = { myTool: tool({ ... }) } satisfies ToolSet
type MyTools = InferUITools<typeof tools>
type MyUIMessage = UIMessage<MyMetadata, MyDataParts, MyTools>
```

## Common Gotchas

1. **Tool part types are `tool-${toolName}`** not generic `tool-call`
2. **Data parts need `id` for reconciliation** - same ID updates existing part
3. **Transient parts only in `onData`** - never in `message.parts`
4. **`sendStart: false` when using custom start** - avoid duplicate start events
5. **`result.consumeStream()`** - call without await for disconnect handling

### cookbook/ai/tools.ts
/**
 * AI tool definitions
 * Includes server-side, client-side, and human-in-the-loop tools
 */
import {
  tool,
  ToolSet,
  InferUITools,
  InferToolInput,
  InferToolOutput,
  UIMessageStreamWriter,
  UIMessage,
} from 'ai'
import { z } from 'zod'
import type { DataParts } from '../types/message'

// === Human-in-the-loop Tool ===
// No execute - requires user confirmation on client
export const confirmAction = tool({
  description: 'Ask the user to confirm an action before proceeding',
  inputSchema: z.object({
    action: z.string().describe('The action to confirm'),
    details: z.string().describe('Details about what will happen'),
    severity: z
      .enum(['low', 'medium', 'high'])
      .describe('How impactful is this action'),
  }),
  outputSchema: z.object({
    confirmed: z.boolean(),
    reason: z.string().optional(),
  }),
})

export type ConfirmActionInput = InferToolInput<typeof confirmAction>
export type ConfirmActionOutput = InferToolOutput<typeof confirmAction>

// === Server-side Tool with Data Streaming ===
// Streams progress via data parts
export const generateProposal = (
  writer: UIMessageStreamWriter<UIMessage<never, DataParts>>
) =>
  tool({
    description: 'Generate an insurance proposal for the user',
    inputSchema: z.object({
      coverage: z.string().describe('Type of coverage requested'),
      amount: z.number().describe('Coverage amount'),
      details: z.string().optional().describe('Additional details'),
    }),
    execute: async ({ coverage, amount, details }, { toolCallId }) => {
      // Initial loading state
      writer.write({
        type: 'data-proposal',
        id: toolCallId,
        data: {
          status: 'loading',
          title: `${coverage} Proposal`,
        },
      })

      // Simulate processing
      await new Promise((resolve) => setTimeout(resolve, 1000))

      // Update to generating
      writer.write({
        type: 'data-proposal',
        id: toolCallId,
        data: {
          status: 'generating',
          title: `${coverage} Proposal`,
        },
      })

      // Simulate generation
      await new Promise((resolve) => setTimeout(resolve, 2000))

      // Final result
      const proposalContent = {
        coverage,
        amount,
        details,
        premium: amount * 0.02,
        generatedAt: new Date().toISOString(),
      }

      writer.write({
        type: 'data-proposal',
        id: toolCallId,
        data: {
          status: 'complete',
          title: `${coverage} Proposal`,
          content: proposalContent,
        },
      })

      return {
        success: true,
        proposalId: toolCallId,
        summary: `Generated ${coverage} proposal for $${amount}`,
      }
    },
  })

export type GenerateProposalInput = InferToolInput<
  ReturnType<typeof generateProposal>
>
export type GenerateProposalOutput = InferToolOutput<
  ReturnType<typeof generateProposal>
>

// === Simple Server-side Tool ===
export const getWeatherInfo = tool({
  description: 'Get weather information for a location',
  inputSchema: z.object({
    location: z.string().describe('City or location name'),
  }),
  execute: async ({ location }) => {
    // Simulate API call
    await new Promise((resolve) => setTimeout(resolve, 500))

    const conditions = ['sunny', 'cloudy', 'rainy', 'partly cloudy']
    const condition = conditions[Math.floor(Math.random() * conditions.length)]
    const temperature = Math.floor(Math.random() * 30) + 10

    return {
      location,
      condition,
      temperature,
      unit: 'celsius',
    }
  },
})

// === Client-side Tool (no execute) ===
