/**
 * Bidirectional message mapping between UI and DB formats
 */
import type { MyUIMessagePart } from '../types/message'
import type { DBPart, DBPartSelect } from '../db/schema'

/**
 * Convert UI message parts to database format
 */
export function mapUIPartsToDBParts(
  parts: MyUIMessagePart[],
  messageId: string
): DBPart[] {
  return parts.map((part, index) => {
    const base = { messageId, order: index, type: part.type }

    switch (part.type) {
      case 'text':
        return {
          ...base,
          text_text: part.text,
        }

      case 'reasoning':
        return {
          ...base,
          reasoning_text: part.text,
          providerMetadata: part.providerMetadata,
        }

      case 'source-url':
        return {
          ...base,
          source_url_sourceId: part.sourceId,
          source_url_url: part.url,
          source_url_title: part.title,
          providerMetadata: part.providerMetadata,
        }

      case 'step-start':
        return base

      case 'tool-confirmAction':
        return {
          ...base,
          tool_toolCallId: part.toolCallId,
          tool_state: part.state,
          tool_confirmAction_input:
            part.state === 'input-available' ||
            part.state === 'output-available' ||
            part.state === 'output-error'
              ? part.input
              : undefined,
          tool_confirmAction_output:
            part.state === 'output-available' ? part.output : undefined,
          tool_errorText:
            part.state === 'output-error' ? part.errorText : undefined,
        }

      case 'tool-generateProposal':
        return {
          ...base,
          tool_toolCallId: part.toolCallId,
          tool_state: part.state,
          tool_generateProposal_input:
            part.state === 'input-available' ||
            part.state === 'output-available' ||
            part.state === 'output-error'
              ? part.input
              : undefined,
          tool_generateProposal_output:
            part.state === 'output-available' ? part.output : undefined,
          tool_errorText:
            part.state === 'output-error' ? part.errorText : undefined,
        }

      case 'tool-getWeatherInfo':
        // Simple tool - just store state and result
        return {
          ...base,
          tool_toolCallId: part.toolCallId,
          tool_state: part.state,
        }

      case 'tool-getUserLocation':
        return {
          ...base,
          tool_toolCallId: part.toolCallId,
          tool_state: part.state,
        }

      case 'data-proposal':
        return {
          ...base,
          data_proposal_id: part.id,
          data_proposal_status: part.data.status,
          data_proposal_title: part.data.title,
          data_proposal_content: part.data.content,
        }

      default:
        // Handle unknown types gracefully
        console.warn(`Unknown part type: ${(part as any).type}`)
        return base
    }
  })
}

/**
 * Convert database part to UI format
 */
export function mapDBPartToUIPart(part: DBPartSelect): MyUIMessagePart {
  switch (part.type) {
    case 'text':
      return {
        type: 'text',
        text: part.text_text!,
      }

    case 'reasoning':
      return {
        type: 'reasoning',
        text: part.reasoning_text!,
        providerMetadata: part.providerMetadata ?? undefined,
      }

    case 'source-url':
      return {
        type: 'source-url',
        sourceId: part.source_url_sourceId!,
        url: part.source_url_url!,
        title: part.source_url_title,
        providerMetadata: part.providerMetadata ?? undefined,
      }

    case 'step-start':
      return { type: 'step-start' }

    case 'tool-confirmAction':
      return mapToolPart(part, 'confirmAction', {
        inputKey: 'tool_confirmAction_input',
        outputKey: 'tool_confirmAction_output',
      })

    case 'tool-generateProposal':
      return mapToolPart(part, 'generateProposal', {
        inputKey: 'tool_generateProposal_input',
        outputKey: 'tool_generateProposal_output',
      })

    case 'tool-getWeatherInfo':
    case 'tool-getUserLocation':
      // These tools may not have persisted input/output in this example
      return {
        type: part.type as any,
        toolCallId: part.tool_toolCallId!,
        state: part.tool_state!,
      } as any

    case 'data-proposal':
      return {
        type: 'data-proposal',
        id: part.data_proposal_id!,
        data: {
          status: part.data_proposal_status as any,
          title: part.data_proposal_title,
          content: part.data_proposal_content,
        },
      }

    default:
      throw new Error(`Unknown part type: ${part.type}`)
  }
}

/**
 * Helper to map tool parts with proper state handling
 */
function mapToolPart<T extends string>(
  part: DBPartSelect,
  toolName: T,
  keys: { inputKey: keyof DBPartSelect; outputKey: keyof DBPartSelect }
): MyUIMessagePart {
  const baseToolPart = {
    type: `tool-${toolName}` as const,
    toolCallId: part.tool_toolCallId!,
  }

  const input = part[keys.inputKey]
  const output = part[keys.outputKey]

  switch (part.tool_state) {
    case 'input-streaming':
      return {
        ...baseToolPart,
        state: 'input-streaming',
        input,
      } as any

    case 'input-available':
      return {
        ...baseToolPart,
        state: 'input-available',
        input: input!,
      } as any

    case 'output-available':
      return {
        ...baseToolPart,
        state: 'output-available',
        input: input!,
        output: output!,
      } as any

    case 'output-error':
      return {
        ...baseToolPart,
        state: 'output-error',
        input: input!,
        errorText: part.tool_errorText!,
      } as any

    default:
      throw new Error(`Unknown tool state: ${part.tool_state}`)
  }
}

### SKILL.md
# API Design Skill

This skill allows Claude to automatically design and implement API endpoints following REST or GraphQL best practices when the context suggests an API needs to be created.

## When to Use This Skill

Claude should invoke this skill autonomously when:
- User mentions creating an API endpoint
- Discussion involves building backend routes
- Task requires data exposure via API
- User describes API functionality needed
- Code analysis shows an endpoint is referenced but doesn't exist

## What This Skill Does

Automatically generates a complete API endpoint structure including:
1. Route definition with proper HTTP methods
2. Controller/handler with business logic
3. Service layer for data operations
4. Request/response validation schemas
5. Authentication and authorization middleware
6. Error handling
7. API tests
8. OpenAPI/Swagger documentation

## Framework Detection

The skill detects the project's backend framework and generates appropriate code:
- **Express.js**: Route handlers, middleware
- **Fastify**: Route schemas, hooks
- **NestJS**: Controllers, modules, decorators
- **FastAPI**: Path operations, Pydantic models
- **Flask**: Blueprints, routes
- **Django**: Views, serializers

## Input Parameters

When invoked, the skill expects:
- `endpoint`: Route path (e.g., "/api/users", "/api/posts/:id")
- `method`: HTTP method (GET, POST, PUT, PATCH, DELETE)
- `description`: What the endpoint does
- `authentication`: Whether auth is required (boolean)
- `requestBody`: Request payload structure (if applicable)
- `responseBody`: Response structure

## Generated Structure

### For REST API (Node.js/Express):

```
src/
├── routes/
│   └── users.routes.ts          # Route definitions
├── controllers/
│   └── users.controller.ts      # Request handlers
├── services/
│   └── users.service.ts         # Business logic
├── validators/
│   └── users.validator.ts       # Input validation
├── types/
│   └── users.types.ts           # TypeScript types
├── middleware/
│   ├── auth.middleware.ts       # Authentication
│   └── validate.middleware.ts   # Validation
└── tests/
    └── users.test.ts            # API tests
```

## Component Templates

### 1. Route Definition

```typescript
// routes/users.routes.ts
import { Router } from 'express'
import { UsersController } from '../controllers/users.controller'
import { authenticate } from '../middleware/auth.middleware'
import { validate } from '../middleware/validate.middleware'
import { createUserSchema } from '../validators/users.validator'

const router = Router()
const controller = new UsersController()

router.get('/users', authenticate, controller.getUsers)
router.get('/users/:id', authenticate, controller.getUser)
router.post('/users', authenticate, validate(createUserSchema), controller.createUser)
router.put('/users/:id', authenticate, validate(updateUserSchema), controller.updateUser)
router.delete('/users/:id', authenticate, controller.deleteUser)

export default router
```

### 2. Controller

```typescript
// controllers/users.controller.ts
import { Request, Response, NextFunction } from 'express'
import { UsersService } from '../services/users.service'
import { CreateUserDto, UpdateUserDto } from '../types/users.types'

export class UsersController {
  private usersService: UsersService

  constructor() {
    this.usersService = new UsersService()
  }

  getUsers = async (req: Request, res: Response, next: NextFunction) => {
    try {
      const { page = 1, limit = 20, search } = req.query

      const result = await this.usersService.findAll({
        page: Number(page),
        limit: Number(limit),
        search: search as string,
      })

      res.json({
        success: true,
        data: result.data,
        pagination: result.pagination,
      })
    } catch (error) {
      next(error)
    }
  }

  getUser = async (req: Request, res: Response, next: NextFunction) => {
    try {
      const { id } = req.params
      const user = await this.usersService.findById(id)

      if (!user) {
        return res.status(404).json({
          success: false,
          error: { code: 'USER_NOT_FOUND', message: 'User not found' },
        })
      }

      res.json({
        success: true,
        data: user,
      })
    } catch (error) {
      next(error)
    }
  }

  createUser = async (req: Request, res: Response, next: NextFunction) => {
    try {
      const userData: CreateUserDto = req.body
      const user = await this.usersService.create(userData)

      res.status(201).json({
        success: true,
        data: user,
      })
    } catch (error) {
      next(error)
    }
  }

  updateUser = async (req: Request, res: Response, next: NextFunction) => {
    try {
      const { id } = req.params
      const userData: UpdateUserDto = req.body

      const user = await this.usersService.update(id, userData)

      if (!user) {
        return res.status(404).json({
          success: false,
          error: { code: 'USER_NOT_FOUND', message: 'User not found' },
        })
      }

      res.json({
        success: true,
        data: user,
      })
    } catch (error) {
      next(error)
    }
  }

  deleteUser = async (req: Request, res: Response, next: NextFunction) => {
    try {
      const { id } = req.params
      await this.usersService.delete(id)

      res.status(204).send()
    } catch (error) {
      next(error)
    }
  }
}
```

### 3. Service Layer

```typescript
// services/users.service.ts
import { User } from '../entities/User'
import { CreateUserDto, UpdateUserDto } from '../types/users.types'
import { AppDataSource } from '../config/database'

export class UsersService {
  private userRepository = AppDataSource.getRepository(User)

  async findAll(options: { page: number; limit: number; search?: string }) {
    const { page, limit, search } = options
    const skip = (page - 1) * limit

    const queryBuilder = this.userRepository.createQueryBuilder('user')

    if (search) {
      queryBuilder.where('user.name ILIKE :search OR user.email ILIKE :search', {
        search: `%${search}%`,
      })
    }

    const [data, total] = await queryBuilder
      .skip(skip)
      .take(limit)
      .orderBy('user.createdAt', 'DESC')
      .getManyAndCount()

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
      },
    }
  }

  async findById(id: string): Promise<User | null> {
    return this.userRepository.findOne({ where: { id } })
  }

  async create(data: CreateUserDto): Promise<User> {
    const user = this.userRepository.create(data)
    return this.userRepository.save(user)
  }

  async update(id: string, data: UpdateUserDto): Promise<User | null> {
    await this.userRepository.update(id, data)
    return this.findById(id)
  }

  async delete(id: string): Promise<void> {
    await this.userRepository.delete(id)
  }
}
