## A07: Authentication Failures

### Session Security

```javascript
const session = require('express-session');

app.use(session({
  secret: process.env.SESSION_SECRET,
  name: 'sessionId', // Don't use default name
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: true, // HTTPS only
    httpOnly: true, // No JS access
    sameSite: 'strict', // CSRF protection
    maxAge: 3600000 // 1 hour
  }
}));
```

### JWT Best Practices

```javascript
const jwt = require('jsonwebtoken');

// Sign with strong algorithm
const token = jwt.sign(payload, secret, {
  algorithm: 'HS256',
  expiresIn: '1h',
  issuer: 'your-app'
});

// Verify properly
try {
  const decoded = jwt.verify(token, secret, {
    algorithms: ['HS256'], // Prevent algorithm confusion
    issuer: 'your-app'
  });
} catch (err) {
  // Handle invalid token
}
```

## A08: Software and Data Integrity

### Subresource Integrity

```html
<script
  src="https://cdn.example.com/lib.js"
  integrity="sha384-abc123..."
  crossorigin="anonymous">
</script>
```

### Secure Deserialization

```javascript
// Avoid eval and Function constructor
// Bad
eval(userInput);
new Function(userInput);

// Bad - Arbitrary code execution
const obj = serialize.unserialize(userInput);

// Good - Use JSON
const obj = JSON.parse(userInput);

// Good - Validate schema after parsing
const parsed = JSON.parse(userInput);
const validated = schema.validate(parsed);
```

## A09: Security Logging

```javascript
const winston = require('winston');

const securityLogger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'security.log' })
  ]
});

// Log security events
function logSecurityEvent(event, details) {
  securityLogger.info({
    timestamp: new Date().toISOString(),
    event,
    ...details,
    // Don't log sensitive data
    password: undefined,
    token: undefined
  });
}

// Usage
logSecurityEvent('LOGIN_FAILED', {
  username: req.body.username,
  ip: req.ip,
  userAgent: req.get('User-Agent')
});
```

## A10: Server-Side Request Forgery (SSRF)

### Vulnerable Pattern

```javascript
// User controls URL
const response = await axios.get(req.query.url);
// Attacker uses: http://169.254.169.254/metadata (AWS)
```

### Secure Pattern

```javascript
const { URL } = require('url');

const ALLOWED_HOSTS = ['api.example.com', 'cdn.example.com'];
const BLOCKED_IPS = ['127.0.0.1', 'localhost', '169.254.169.254'];

async function secureFetch(urlString) {
  const url = new URL(urlString);

  // Check allowed hosts
  if (!ALLOWED_HOSTS.includes(url.hostname)) {
    throw new Error('Host not allowed');
  }

  // Block internal IPs
  const ip = await dns.lookup(url.hostname);
  if (BLOCKED_IPS.includes(ip) || ip.startsWith('10.') || ip.startsWith('192.168.')) {
    throw new Error('Internal addresses not allowed');
  }

  return axios.get(urlString);
}
```

