### references/profiles.md
# Profiles

Profiles define site-specific defaults for WordPress connections. The skill loads a profile by name and applies any overrides from environment variables.

## Location

`profiles/<profile-name>.json`

## Example

```json
{
  "name": "example-blog",
  "site_url": "https://blog.example.com",
  "api_url": "https://blog.example.com/wp-json/wp/v2",
  "cli_path": null,
  "env": {
    "username": "WP_USERNAME",
    "app_password": "WP_APP_PASSWORD"
  }
}
```

## Fields

- `name` (string): Profile name.
- `site_url` (string): WordPress site base URL.
- `api_url` (string): WordPress REST API base URL.
- `cli_path` (string|null): Path to the `blog-wordpress` CLI folder. Set to `null` if using `WP_CLI_PATH` env var.
- `env.username` (string): Env var name for the WordPress username.
- `env.app_password` (string): Env var name for the WordPress Application Password.

## Overrides

These environment variables take precedence over profile values:

- `WP_SITE_URL`
- `WP_API_URL`
- `WP_CLI_PATH`
- `WP_USERNAME`
- `WP_APP_PASSWORD`

## Creating Your Own Profile

1. Copy `example-blog.json` to `your-site.json`
2. Update the URLs to match your WordPress site
3. Set `cli_path` to the location of your WordPress CLI, or leave as `null` and set `WP_CLI_PATH`
4. Use `--profile your-site` or set `WP_PROFILE=your-site`

### scripts/setup.sh
#!/usr/bin/env bash
set -euo pipefail

PROFILE="${WP_PROFILE:-example-blog}"

SKILL_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PROFILE_PATH="${SKILL_DIR}/profiles/${PROFILE}.json"

if [[ ! -f "$PROFILE_PATH" ]]; then
  echo "Profile not found: $PROFILE_PATH" >&2
  exit 2
fi

if ! command -v node >/dev/null 2>&1; then
  if command -v brew >/dev/null 2>&1; then
    echo "Node.js not found. Installing Node.js via brew..." >&2
    brew install node
  elif command -v apt-get >/dev/null 2>&1; then
    echo "Node.js not found. Installing Node.js via apt-get..." >&2
    if command -v sudo >/dev/null 2>&1; then
      sudo apt-get update
      sudo apt-get install -y nodejs npm
    else
      apt-get update
      apt-get install -y nodejs npm
    fi
  else
    echo "Node.js 16+ is required but not found. Install Node.js and ensure 'node' is on PATH." >&2
    exit 2
  fi
fi

if ! command -v node >/dev/null 2>&1; then
  echo "Node.js install did not update PATH in this session. Restart your shell and rerun setup." >&2
  exit 2
fi

if ! command -v npm >/dev/null 2>&1; then
  echo "npm is required but not found. Install Node.js 16+ (includes npm) and rerun setup." >&2
  exit 2
fi

NODE_VERSION="$(node -v | sed 's/^v//')"
NODE_MAJOR="${NODE_VERSION%%.*}"
if [[ "${NODE_MAJOR:-0}" -lt 16 ]]; then
  echo "Node.js $NODE_VERSION found, but 16+ is required. Upgrade Node.js and rerun setup." >&2
  exit 2
fi

CLI_PATH="${WP_CLI_PATH:-}"
if [[ -z "$CLI_PATH" ]]; then
  CLI_PATH="$(node -e "const fs=require('fs');const p=JSON.parse(fs.readFileSync('${PROFILE_PATH}','utf8'));process.stdout.write(p.cli_path||'');")"
fi

if [[ -z "$CLI_PATH" || ! -d "$CLI_PATH" ]]; then
  ALT_PATH="${SKILL_DIR}/tools/blog-wordpress"
  if [[ -d "$ALT_PATH" ]]; then
    CLI_PATH="$ALT_PATH"
  fi
fi

if [[ -z "$CLI_PATH" || ! -d "$CLI_PATH" ]]; then
  echo "WordPress CLI path not found. Set WP_CLI_PATH or update profile cli_path (you can place it under tools/blog-wordpress in this skill)." >&2
  exit 2
fi

missing=()
if [[ -z "${WP_USERNAME:-}" ]]; then
  missing+=("WP_USERNAME")
fi
if [[ -z "${WP_APP_PASSWORD:-}" ]]; then
  missing+=("WP_APP_PASSWORD")
fi
if [[ "${#missing[@]}" -gt 0 ]]; then
  echo "Missing required environment variables: ${missing[*]}. Set them and rerun setup." >&2
  exit 2
fi

pushd "$CLI_PATH" >/dev/null
if [[ -f "package-lock.json" ]]; then
  npm ci --no-audit --no-fund
else
  npm install --no-audit --no-fund
fi
npm run validate
popd >/dev/null

### scripts/wp-content.mjs
#!/usr/bin/env node
import fs from "fs";
import path from "path";
import { fileURLToPath, pathToFileURL } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

function parseArgs(argv) {
  const flags = {};
  const positionals = [];
  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg.startsWith("--")) {
      const key = arg.slice(2);
      const next = argv[i + 1];
      if (next && !next.startsWith("--")) {
        flags[key] = next;
        i += 2;
      } else {
        flags[key] = true;
        i += 1;
      }
    } else {
      positionals.push(arg);
      i += 1;
    }
  }
  return { flags, positionals };
}

function loadProfile(profileName) {
  const skillDir = path.resolve(__dirname, "..");
  const profilePath = path.join(skillDir, "profiles", `${profileName}.json`);
  if (!fs.existsSync(profilePath)) {
    throw new Error(`Profile not found: ${profilePath}`);
  }
  return JSON.parse(fs.readFileSync(profilePath, "utf8"));
}

function resolveCliPath(profile) {
  const envOverride = process.env.WP_CLI_PATH;
  if (envOverride) {
    return envOverride;
  }
  if (profile.cli_path) {
    return profile.cli_path;
  }
  throw new Error("WordPress CLI path not set. Use WP_CLI_PATH or profile cli_path.");
}

function applyProfileEnv(profile) {
  if (!process.env.WP_SITE_URL && profile.site_url) {
    process.env.WP_SITE_URL = profile.site_url;
  }
  if (!process.env.WP_API_URL && profile.api_url) {
    process.env.WP_API_URL = profile.api_url;
  }
}

function ensureAuthEnv() {
  if (!process.env.WP_USERNAME || !process.env.WP_APP_PASSWORD) {
    throw new Error("Missing WP_USERNAME or WP_APP_PASSWORD.");
  }
}

function parseListQuery(value) {
  if (!value) return undefined;
  return value
    .split(",")
    .map(v => v.trim())
    .filter(Boolean)
    .join(",");
}

function parseIdList(value) {
  if (!value) return undefined;
  return value
    .split(",")
    .map(v => v.trim())
    .filter(Boolean)
    .map(v => {
      const n = Number(v);
      return Number.isFinite(n) ? n : v;
    });
}

function parseNumber(value) {
  if (value === undefined) return undefined;
  const n = Number(value);
  return Number.isFinite(n) ? n : undefined;
}

async function getClient(cliPath) {
  const absCliPath = path.resolve(cliPath);
  if (!fs.existsSync(absCliPath)) {
    throw new Error(`WordPress CLI path not found: ${absCliPath}`);
  }
  const cliEntry = path.join(absCliPath, "wp-cli.js");
  if (!fs.existsSync(cliEntry)) {
    throw new Error(`WordPress CLI entry not found: ${cliEntry}`);
  }
  const nodeModules = path.join(absCliPath, "node_modules");
  if (!fs.existsSync(nodeModules)) {
    throw new Error("CLI dependencies are not installed. Run setup.sh or setup.ps1 first.");
  }

  process.chdir(absCliPath);
  applyProfileEnv(activeProfile);

  const moduleUrl = pathToFileURL(cliEntry);
  const mod = await import(moduleUrl.href);
  return new mod.WordPressClient();
}

function readContent(flags) {
  if (flags["content-file"]) {
    return fs.readFileSync(flags["content-file"], "utf8");
  }
  if (flags.content) {
    return flags.content;
  }
  return "";
}

function formatOutput(data, jsonOutput) {
  if (jsonOutput) {
    console.log(JSON.stringify(data, null, 2));
    return;
  }
  console.log(data);
}

const argv = process.argv.slice(2);
const { flags, positionals } = parseArgs(argv);
const profileName = flags.profile || process.env.WP_PROFILE || "example-blog";
const jsonOutput = Boolean(flags.json);

let activeProfile;
try {
  activeProfile = loadProfile(profileName);
} catch (error) {
  console.error(`Error: ${error.message}`);
  process.exit(2);
}

let client;
try {
  client = await getClient(resolveCliPath(activeProfile));
  ensureAuthEnv();
} catch (error) {
  console.error(`Error: ${error.message}`);
  process.exit(2);
}

const command = positionals[0];
const subcommand = positionals[1];

if (!command || command === "help" || command === "--help") {
  console.log(`
WordPress Content Manager

Usage:
  node wp-content.mjs site info [--json]
  node wp-content.mjs posts list [--status <status>] [--search <text>] [--categories 1,2] [--tags 3,4] [--after <date>] [--before <date>] [--page <n>] [--per_page <n>] [--json]
  node wp-content.mjs posts get <id> [--json]
  node wp-content.mjs posts create --title <title> [--content <html>] [--content-file <path>] [--status <status>] [--date <iso>] [--categories 1,2] [--tags 3,4]
  node wp-content.mjs posts update <id> [--title <title>] [--content <html>] [--content-file <path>] [--status <status>] [--date <iso>] [--categories 1,2] [--tags 3,4]
  node wp-content.mjs posts delete <id>
  node wp-content.mjs posts delete-many [filters] [--dry-run] [--confirm]

Profiles:
  --profile <name> or WP_PROFILE=<name>
`);
  process.exit(0);
}

if (command === "site" && subcommand === "info") {
  try {
    const info = await client.getSiteInfo();
    formatOutput(info, jsonOutput);
  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }
  process.exit(0);
}

if (command === "posts") {
  if (subcommand === "list") {
    const params = {
      status: flags.status,
      search: flags.search,
      categories: parseListQuery(flags.categories),
      tags: parseListQuery(flags.tags),
      after: flags.after,
      before: flags.before,
      page: parseNumber(flags.page),
      per_page: parseNumber(flags.per_page),
      orderby: flags.orderby,
      order: flags.order
    };

    try {
      const posts = await client.listPosts(Object.fromEntries(Object.entries(params).filter(([, v]) => v)));
      if (jsonOutput) {
        formatOutput(posts, true);
      } else {
        posts.forEach(post => {
          console.log(`[${post.id}] ${post.title?.rendered || ""}`);
          console.log(`  Status: ${post.status} | Date: ${post.date}`);
          console.log(`  Link: ${post.link}`);
        });
      }
    } catch (error) {
      console.error(`Error: ${error.message}`);
      process.exit(1);
    }
    process.exit(0);
  }

  if (subcommand === "get") {
    const id = positionals[2];
    if (!id) {
      console.error("Error: Post ID required.");
      process.exit(2);
    }
    try {
      const post = await client.getPost(id);
      formatOutput(post, jsonOutput);
    } catch (error) {
      console.error(`Error: ${error.message}`);
      process.exit(1);
    }
    process.exit(0);
  }

  if (subcommand === "create") {
    const title = flags.title;
    if (!title) {
      console.error("Error: --title is required.");
      process.exit(2);
    }
    const content = readContent(flags);
    const data = {
      title,
      content,
      status: flags.status || "draft",
      date: flags.date,
      categories: parseIdList(flags.categories),
      tags: parseIdList(flags.tags)
    };

    try {
      const post = await client.createPost(Object.fromEntries(Object.entries(data).filter(([, v]) => v)));
      formatOutput(post, jsonOutput);
    } catch (error) {
      console.error(`Error: ${error.message}`);
      process.exit(1);
    }
    process.exit(0);
  }

  if (subcommand === "update") {
    const id = positionals[2];
    if (!id) {
      console.error("Error: Post ID required.");
      process.exit(2);
    }
    const content = readContent(flags);
    const data = {
      title: flags.title,
      content: flags.content || flags["content-file"] ? content : undefined,
      status: flags.status,
      date: flags.date,
      categories: parseIdList(flags.categories),
      tags: parseIdList(flags.tags)
    };

    try {
      const post = await client.updatePost(id, Object.fromEntries(Object.entries(data).filter(([, v]) => v)));
      formatOutput(post, jsonOutput);
    } catch (error) {
      console.error(`Error: ${error.message}`);
      process.exit(1);
    }
    process.exit(0);
  }

  if (subcommand === "delete") {
    const id = positionals[2];
    if (!id) {
      console.error("Error: Post ID required.");
      process.exit(2);
    }
    try {
      const result = await client.deletePost(id);
      formatOutput(result, jsonOutput);
    } catch (error) {
      console.error(`Error: ${error.message}`);
      process.exit(1);
    }
    process.exit(0);
  }

  if (subcommand === "delete-many") {
    const dryRun = !flags.confirm || Boolean(flags["dry-run"]);
    const params = {
      status: flags.status,
      search: flags.search,
      categories: parseListQuery(flags.categories),
      tags: parseListQuery(flags.tags),
      after: flags.after,
      before: flags.before,
      page: parseNumber(flags.page),
      per_page: parseNumber(flags.per_page) || 100
    };

    try {
      const posts = await client.listPosts(Object.fromEntries(Object.entries(params).filter(([, v]) => v)));
      const summary = posts.map(p => ({ id: p.id, title: p.title?.rendered || "", status: p.status }));
      if (dryRun) {
        formatOutput({ dry_run: true, count: summary.length, posts: summary }, jsonOutput);
        process.exit(0);
      }

      const results = [];
      for (const post of posts) {
        const res = await client.deletePost(post.id);
        results.push({ id: post.id, status: res?.status || "deleted" });
      }
      formatOutput({ deleted: results.length, results }, jsonOutput);
    } catch (error) {
      console.error(`Error: ${error.message}`);
      process.exit(1);
    }
    process.exit(0);
  }
}

console.error(`Error: Unknown command "${command} ${subcommand || ""}". Use "help" for usage.`);
process.exit(2);

