  dashboard.id = null;
  dashboard.uid = null;
  dashboard.title = options.title ?? `${source.dashboard.title} (Copy)`;

  const result = await client.saveDashboard({
    dashboard,
    folderUid: options.folder ?? source.meta.folderUid,
    message: options.message ?? `Cloned from ${uid}`,
