        EF.CompileAsyncQuery((AppDbContext context, Guid id) =>
            context.Users
                .Include(u => u.Roles)
                .FirstOrDefaultAsync(u => u.Id == id));

    public async Task<User?> GetUserByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
