        foreach (var batch in userIds.Chunk(batchSize))
        {
            await _context.Users
                .Where(u => batch.Contains(u.Id))
                .ExecuteUpdateAsync(setters => setters
                    .SetProperty(u => u.LastLoginAt, DateTime.UtcNow), cancellationToken);
        }
    }
