## Frontend Streaming Component

```tsx
// frontend/src/components/chat/StreamingMessage.tsx
'use client';

import { useState, useEffect, useRef } from 'react';
import { cn } from '@/lib/utils';

interface StreamingMessageProps {
  userId: string;
  message: string;
  token: string;
  onComplete: (response: string, conversationId: number) => void;
}

interface StreamEvent {
  type: 'start' | 'text' | 'tool_call' | 'tool_result' | 'error' | 'done' | 'thinking';
  content?: string;
  name?: string;
  message?: string;
  conversation_id?: number;
}

export function StreamingMessage({
  userId,
  message,
  token,
  onComplete,
}: StreamingMessageProps) {
  const [text, setText] = useState('');
  const [toolCalls, setToolCalls] = useState<string[]>([]);
  const [isStreaming, setIsStreaming] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const conversationIdRef = useRef<number | null>(null);

  useEffect(() => {
    const controller = new AbortController();

    async function startStream() {
      try {
        const response = await fetch(
          `${process.env.NEXT_PUBLIC_API_URL}/api/${userId}/chat/stream`,
          {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${token}`,
            },
            body: JSON.stringify({ message }),
            signal: controller.signal,
          }
        );

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }

        const reader = response.body?.getReader();
        if (!reader) throw new Error('No reader');

        const decoder = new TextDecoder();
        let buffer = '';
        let fullText = '';

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (!line.startsWith('data: ')) continue;

            const data = line.slice(6);
            if (data === '[DONE]') {
              setIsStreaming(false);
              onComplete(fullText, conversationIdRef.current || 0);
              return;
            }

            try {
              const event: StreamEvent = JSON.parse(data);

              switch (event.type) {
                case 'start':
                  if (event.conversation_id) {
                    conversationIdRef.current = event.conversation_id;
                  }
                  break;

                case 'text':
                  if (event.content) {
                    fullText += event.content;
                    setText(fullText);
                  }
                  break;

                case 'tool_call':
                  if (event.name) {
                    setToolCalls(prev => [...prev, event.name!]);
                  }
                  break;

                case 'error':
                  setError(event.message || 'An error occurred');
                  setIsStreaming(false);
                  break;

                case 'done':
                  setIsStreaming(false);
                  onComplete(fullText, conversationIdRef.current || 0);
                  break;
              }
            } catch (e) {
              console.error('Parse error:', e);
            }
          }
        }

        setIsStreaming(false);
        onComplete(fullText, conversationIdRef.current || 0);
      } catch (err) {
        if (err instanceof Error && err.name !== 'AbortError') {
          setError(err.message);
          setIsStreaming(false);
        }
      }
    }

    startStream();

    return () => controller.abort();
  }, [userId, message, token, onComplete]);

  return (
    <div className="space-y-2">
      {/* Tool calls indicator */}
      {toolCalls.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {toolCalls.map((tool, i) => (
            <span
              key={i}
              className="text-xs px-2 py-0.5 bg-muted rounded-full"
            >
              {tool}
            </span>
          ))}
        </div>
      )}

      {/* Message text */}
      <div className={cn(
        "prose prose-sm dark:prose-invert max-w-none",
        error && "text-destructive"
      )}>
        {error || text}
        {isStreaming && (
          <span className="inline-block w-2 h-4 ml-0.5 bg-foreground animate-pulse" />
        )}
      </div>
    </div>
  );
}
