#!/usr/bin/env python3
"""
Test script for SSE streaming endpoint.
Run this to verify the streaming chat endpoint is working correctly.

Usage:
    # First start the backend server:
    cd backend && uv run uvicorn src.main:app --reload

    # Then run this test:
