## Example 2: User Management API

Complete user CRUD operations with proper typing.

```javascript
import { GraphQLObjectType, GraphQLString, GraphQLID, GraphQLList, GraphQLNonNull, GraphQLSchema } from 'graphql';
import { randomBytes } from 'crypto';

// In-memory database
const users = new Map();

// User Type
const UserType = new GraphQLObjectType({
  name: 'User',
  fields: {
    id: { type: new GraphQLNonNull(GraphQLID) },
    name: { type: new GraphQLNonNull(GraphQLString) },
    email: { type: new GraphQLNonNull(GraphQLString) },
    bio: { type: GraphQLString }
  }
});

// Query Type
const QueryType = new GraphQLObjectType({
  name: 'Query',
  fields: {
    user: {
      type: UserType,
      args: {
        id: { type: new GraphQLNonNull(GraphQLID) }
      },
      resolve: (_, { id }) => {
        const user = users.get(id);
        if (!user) {
          throw new Error(`User with ID ${id} not found`);
        }
        return user;
      }
    },
    users: {
      type: new GraphQLList(new GraphQLNonNull(UserType)),
      resolve: () => {
        return Array.from(users.values());
      }
    }
  }
});

// Mutation Type
const MutationType = new GraphQLObjectType({
  name: 'Mutation',
  fields: {
    createUser: {
      type: UserType,
      args: {
        name: { type: new GraphQLNonNull(GraphQLString) },
        email: { type: new GraphQLNonNull(GraphQLString) },
        bio: { type: GraphQLString }
      },
      resolve: (_, { name, email, bio }) => {
        const id = randomBytes(10).toString('hex');
        const user = { id, name, email, bio };
        users.set(id, user);
        return user;
      }
    },
    updateUser: {
      type: UserType,
      args: {
        id: { type: new GraphQLNonNull(GraphQLID) },
        name: { type: GraphQLString },
        email: { type: GraphQLString },
        bio: { type: GraphQLString }
      },
      resolve: (_, { id, ...updates }) => {
        const user = users.get(id);
        if (!user) {
          throw new Error(`User with ID ${id} not found`);
        }
        Object.assign(user, updates);
        return user;
      }
    },
    deleteUser: {
      type: GraphQLID,
      args: {
        id: { type: new GraphQLNonNull(GraphQLID) }
      },
      resolve: (_, { id }) => {
        if (!users.has(id)) {
          throw new Error(`User with ID ${id} not found`);
        }
        users.delete(id);
        return id;
      }
    }
  }
});

// Create schema
const schema = new GraphQLSchema({
  query: QueryType,
  mutation: MutationType
});
```

**Usage:**

```graphql
# Create user
mutation {
  createUser(name: "Alice", email: "alice@example.com", bio: "Developer") {
    id
    name
    email
  }
}

# Get all users
query {
  users {
    id
    name
    email
  }
}

# Update user
mutation {
  updateUser(id: "abc123", bio: "Senior Developer") {
    id
    name
    bio
  }
}
```

