import { PubSub } from 'graphql-subscriptions';
import { createServer } from 'http';
import { WebSocketServer } from 'ws';
import { useServer } from 'graphql-ws/lib/use/ws';
import { execute, subscribe } from 'graphql';
import express from 'express';
import { createHandler } from 'graphql-http/lib/use/express';

const pubsub = new PubSub();

// Events
const MESSAGE_SENT = 'MESSAGE_SENT';
const USER_JOINED = 'USER_JOINED';
const TYPING_STARTED = 'TYPING_STARTED';

// Types
const MessageType = new GraphQLObjectType({
  name: 'Message',
  fields: {
    id: { type: new GraphQLNonNull(GraphQLID) },
    text: { type: new GraphQLNonNull(GraphQLString) },
    author: { type: new GraphQLNonNull(GraphQLString) },
    channelId: { type: new GraphQLNonNull(GraphQLID) },
    timestamp: { type: new GraphQLNonNull(GraphQLString) }
  }
});

const UserType = new GraphQLObjectType({
  name: 'User',
  fields: {
    id: { type: new GraphQLNonNull(GraphQLID) },
    name: { type: new GraphQLNonNull(GraphQLString) }
  }
});

const TypingEventType = new GraphQLObjectType({
  name: 'TypingEvent',
  fields: {
    userId: { type: new GraphQLNonNull(GraphQLID) },
    userName: { type: new GraphQLNonNull(GraphQLString) },
    channelId: { type: new GraphQLNonNull(GraphQLID) }
  }
});

// Storage
const messages = [];
let messageIdCounter = 1;

// Query
const QueryType = new GraphQLObjectType({
  name: 'Query',
  fields: {
    messages: {
      type: new GraphQLList(new GraphQLNonNull(MessageType)),
      args: {
        channelId: { type: new GraphQLNonNull(GraphQLID) }
      },
      resolve: (_, { channelId }) => {
        return messages.filter(m => m.channelId === channelId);
      }
    }
  }
});

// Mutation
const MutationType = new GraphQLObjectType({
  name: 'Mutation',
  fields: {
    sendMessage: {
      type: MessageType,
      args: {
        text: { type: new GraphQLNonNull(GraphQLString) },
        author: { type: new GraphQLNonNull(GraphQLString) },
        channelId: { type: new GraphQLNonNull(GraphQLID) }
      },
      resolve: (_, { text, author, channelId }) => {
        const message = {
          id: String(messageIdCounter++),
          text,
          author,
          channelId,
          timestamp: new Date().toISOString()
        };

        messages.push(message);

        // Publish to subscribers
        pubsub.publish(MESSAGE_SENT, { messageSent: message });

        return message;
      }
    },
    startTyping: {
      type: TypingEventType,
      args: {
        userId: { type: new GraphQLNonNull(GraphQLID) },
        userName: { type: new GraphQLNonNull(GraphQLString) },
        channelId: { type: new GraphQLNonNull(GraphQLID) }
      },
      resolve: (_, args) => {
        const event = {
          userId: args.userId,
          userName: args.userName,
          channelId: args.channelId
        };

        pubsub.publish(TYPING_STARTED, { typingStarted: event });

        return event;
      }
    }
  }
});

// Subscription
const SubscriptionType = new GraphQLObjectType({
  name: 'Subscription',
  fields: {
    messageSent: {
      type: MessageType,
      args: {
        channelId: { type: GraphQLID }
      },
      subscribe: (_, { channelId }) => {
        if (channelId) {
          // Filter by channel
          return pubsub.asyncIterator([MESSAGE_SENT]);
        }
        return pubsub.asyncIterator([MESSAGE_SENT]);
      },
      resolve: (payload, args) => {
        // Filter in resolve if channelId provided
        if (args.channelId && payload.messageSent.channelId !== args.channelId) {
          return null;
        }
        return payload.messageSent;
      }
    },
    typingStarted: {
      type: TypingEventType,
      args: {
        channelId: { type: new GraphQLNonNull(GraphQLID) }
      },
      subscribe: (_, { channelId }) => {
        return pubsub.asyncIterator([TYPING_STARTED]);
      },
      resolve: (payload, { channelId }) => {
        if (payload.typingStarted.channelId !== channelId) {
          return null;
        }
        return payload.typingStarted;
      }
    }
  }
});

const schema = new GraphQLSchema({
  query: QueryType,
  mutation: MutationType,
  subscription: SubscriptionType
});

// Server setup
const app = express();

app.all('/graphql', createHandler({ schema }));

const httpServer = createServer(app);

// WebSocket server
const wsServer = new WebSocketServer({
  server: httpServer,
  path: '/graphql'
});

useServer(
  {
    schema,
    execute,
    subscribe,
    context: (ctx) => {
      return {
        connectionParams: ctx.connectionParams
      };
    }
  },
  wsServer
);

httpServer.listen(4000, () => {
  console.log('Server running on http://localhost:4000/graphql');
  console.log('WebSocket on ws://localhost:4000/graphql');
});
```

**Client Usage:**

```graphql
# Subscribe to messages
subscription {
  messageSent(channelId: "1") {
    id
    text
    author
    timestamp
  }
}

# Send message (triggers subscription)
mutation {
  sendMessage(
    text: "Hello everyone!"
    author: "Alice"
    channelId: "1"
  ) {
    id
    text
  }
}

# Subscribe to typing events
subscription {
  typingStarted(channelId: "1") {
    userName
  }
}
```

