## Example 12: Custom Scalar Types

Implementing custom scalars for dates, JSON, and more.

```javascript
import { GraphQLScalarType, GraphQLObjectType, GraphQLString, GraphQLID, GraphQLNonNull, GraphQLSchema, Kind } from 'graphql';

// DateTime Scalar
const DateTimeScalar = new GraphQLScalarType({
  name: 'DateTime',
  description: 'ISO-8601 DateTime string',

  serialize(value) {
    // Sent to client
    if (value instanceof Date) {
      return value.toISOString();
    }
    if (typeof value === 'string') {
      return new Date(value).toISOString();
    }
    throw new Error('DateTime must be a Date object or ISO string');
  },

  parseValue(value) {
    // From variables
    const date = new Date(value);
    if (isNaN(date.getTime())) {
      throw new Error('Invalid DateTime value');
    }
    return date;
  },

  parseLiteral(ast) {
    // From query string
    if (ast.kind === Kind.STRING) {
      const date = new Date(ast.value);
      if (isNaN(date.getTime())) {
        throw new Error('Invalid DateTime literal');
      }
      return date;
    }
    throw new Error('DateTime must be a string');
  }
});

// JSON Scalar
const JSONScalar = new GraphQLScalarType({
  name: 'JSON',
  description: 'Arbitrary JSON value',

  serialize(value) {
    return value;
  },

  parseValue(value) {
    return value;
  },

  parseLiteral(ast) {
    switch (ast.kind) {
      case Kind.STRING:
      case Kind.BOOLEAN:
        return ast.value;
      case Kind.INT:
      case Kind.FLOAT:
        return parseFloat(ast.value);
      case Kind.OBJECT:
        return parseObject(ast);
      case Kind.LIST:
        return ast.values.map(n => JSONScalar.parseLiteral(n));
      default:
        return null;
    }
  }
});

function parseObject(ast) {
  const value = Object.create(null);
  ast.fields.forEach(field => {
    value[field.name.value] = JSONScalar.parseLiteral(field.value);
  });
  return value;
}

// Email Scalar with validation
const EmailScalar = new GraphQLScalarType({
  name: 'Email',
  description: 'Valid email address',

  serialize(value) {
    if (typeof value !== 'string') {
      throw new Error('Email must be a string');
    }
    if (!isValidEmail(value)) {
      throw new Error('Invalid email format');
    }
    return value;
  },

  parseValue(value) {
    if (!isValidEmail(value)) {
      throw new Error('Invalid email format');
    }
    return value;
  },

  parseLiteral(ast) {
    if (ast.kind !== Kind.STRING) {
      throw new Error('Email must be a string');
    }
    if (!isValidEmail(ast.value)) {
      throw new Error('Invalid email format');
    }
    return ast.value;
  }
});

function isValidEmail(email) {
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return re.test(email);
}

// Use in schema
const EventType = new GraphQLObjectType({
  name: 'Event',
  fields: {
    id: { type: new GraphQLNonNull(GraphQLID) },
    name: { type: new GraphQLNonNull(GraphQLString) },
    startTime: { type: new GraphQLNonNull(DateTimeScalar) },
    endTime: { type: DateTimeScalar },
    metadata: { type: JSONScalar },
    organizerEmail: { type: new GraphQLNonNull(EmailScalar) }
  }
});

const QueryType = new GraphQLObjectType({
  name: 'Query',
  fields: {
    event: {
      type: EventType,
      args: {
        id: { type: new GraphQLNonNull(GraphQLID) }
      },
      resolve: () => ({
        id: '1',
        name: 'GraphQL Workshop',
        startTime: new Date('2025-01-15T10:00:00Z'),
        endTime: new Date('2025-01-15T12:00:00Z'),
        metadata: {
          location: 'Room 101',
          capacity: 50,
          tags: ['workshop', 'graphql']
        },
        organizerEmail: 'organizer@example.com'
      })
    },
    now: {
      type: DateTimeScalar,
      resolve: () => new Date()
    }
  }
});

const schema = new GraphQLSchema({
  query: QueryType,
  types: [DateTimeScalar, JSONScalar, EmailScalar]
});
```

**Usage:**

```graphql
query {
  event(id: "1") {
    name
    startTime
    endTime
    metadata
    organizerEmail
  }
  now
}

# Result:
{
  "event": {
    "name": "GraphQL Workshop",
    "startTime": "2025-01-15T10:00:00.000Z",
    "endTime": "2025-01-15T12:00:00.000Z",
    "metadata": {
      "location": "Room 101",
      "capacity": 50,
      "tags": ["workshop", "graphql"]
    },
    "organizerEmail": "organizer@example.com"
  },
  "now": "2025-10-18T12:30:45.123Z"
}
```

