```typescript
// features/products/types/product.types.ts
export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  images: string[];
  category: string;
  stock: number;
  rating: number;
}

export interface ProductFilters {
  category?: string;
  minPrice?: number;
  maxPrice?: number;
  inStock?: boolean;
  rating?: number;
}

// features/products/services/productService.ts
export class ProductService {
  constructor(private apiClient: ApiClient) {}

  async getProducts(filters?: ProductFilters): Promise<Product[]> {
    const params = new URLSearchParams();

    if (filters?.category) params.append('category', filters.category);
    if (filters?.minPrice) params.append('minPrice', String(filters.minPrice));
    if (filters?.maxPrice) params.append('maxPrice', String(filters.maxPrice));

    const response = await this.apiClient.get(`/products?${params}`);
    return response.data;
  }

  async getProduct(id: string): Promise<Product> {
    const response = await this.apiClient.get(`/products/${id}`);
    return response.data;
  }

  async searchProducts(query: string): Promise<Product[]> {
    const response = await this.apiClient.get(`/products/search?q=${query}`);
    return response.data;
  }
}

// features/products/store/productStore.ts
import { create } from 'zustand';
import { devtools } from 'zustand/middleware';

interface ProductState {
  products: Product[];
  selectedProduct: Product | null;
  filters: ProductFilters;
  loading: boolean;
  error: string | null;

  setProducts: (products: Product[]) => void;
  setSelectedProduct: (product: Product | null) => void;
  setFilters: (filters: ProductFilters) => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
}

export const useProductStore = create<ProductState>()(
  devtools((set) => ({
    products: [],
    selectedProduct: null,
    filters: {},
    loading: false,
    error: null,

    setProducts: (products) => set({ products }),
    setSelectedProduct: (selectedProduct) => set({ selectedProduct }),
    setFilters: (filters) => set({ filters }),
    setLoading: (loading) => set({ loading }),
    setError: (error) => set({ error })
  }))
);

// features/products/hooks/useProducts.ts
export function useProducts(filters?: ProductFilters) {
  const productService = useProductService();
  const setProducts = useProductStore(state => state.setProducts);
  const setLoading = useProductStore(state => state.setLoading);
  const setError = useProductStore(state => state.setError);

  return useQuery({
    queryKey: ['products', filters],
    queryFn: async () => {
      setLoading(true);
      try {
        const products = await productService.getProducts(filters);
        setProducts(products);
        return products;
      } catch (error) {
        setError(error.message);
        throw error;
      } finally {
        setLoading(false);
      }
    },
    staleTime: 5 * 60 * 1000
  });
