## 7. Admin Dashboard with RBAC

Complete role-based access control system.

### Implementation

```typescript
// core/rbac/permissions.ts
export const PERMISSIONS = {
  // Users
  'users:read': 'View users',
  'users:create': 'Create users',
  'users:update': 'Update users',
  'users:delete': 'Delete users',

  // Posts
  'posts:read': 'View posts',
  'posts:create': 'Create posts',
  'posts:update': 'Update posts',
  'posts:delete': 'Delete posts',
  'posts:publish': 'Publish posts',

  // Settings
  'settings:read': 'View settings',
  'settings:update': 'Update settings'
} as const;

export type Permission = keyof typeof PERMISSIONS;

export const ROLES = {
  admin: Object.keys(PERMISSIONS) as Permission[],
  editor: [
    'users:read',
    'posts:read',
    'posts:create',
    'posts:update',
    'posts:publish'
  ] as Permission[],
  author: [
    'posts:read',
    'posts:create',
    'posts:update'
  ] as Permission[],
  viewer: [
    'users:read',
    'posts:read'
  ] as Permission[]
};

export type Role = keyof typeof ROLES;

// core/rbac/useAuthorization.ts
export function useAuthorization() {
  const { user } = useAuth();

  const hasPermission = useCallback(
    (permission: Permission): boolean => {
      if (!user) return false;

      const userPermissions = user.roles.flatMap(role => ROLES[role] || []);
      return userPermissions.includes(permission);
    },
    [user]
  );

  const hasAnyPermission = useCallback(
    (permissions: Permission[]): boolean => {
      return permissions.some(hasPermission);
    },
    [hasPermission]
  );

  const hasAllPermissions = useCallback(
    (permissions: Permission[]): boolean => {
      return permissions.every(hasPermission);
    },
    [hasPermission]
  );

  const hasRole = useCallback(
    (role: Role): boolean => {
      return user?.roles.includes(role) ?? false;
    },
    [user]
  );

  return {
    hasPermission,
    hasAnyPermission,
    hasAllPermissions,
    hasRole
  };
}

// shared/components/Can.tsx
export function Can({
  permission,
  permissions,
  requireAll = false,
  fallback,
  children
}: {
  permission?: Permission;
  permissions?: Permission[];
  requireAll?: boolean;
  fallback?: React.ReactNode;
  children: React.ReactNode;
}) {
  const { hasPermission, hasAnyPermission, hasAllPermissions } = useAuthorization();

  let authorized = false;

  if (permission) {
    authorized = hasPermission(permission);
  } else if (permissions) {
    authorized = requireAll
      ? hasAllPermissions(permissions)
      : hasAnyPermission(permissions);
  }

  if (!authorized) {
    return <>{fallback || null}</>;
  }

  return <>{children}</>;
}

// Usage
function UserManagement() {
  return (
    <div>
      <h1>User Management</h1>

      <Can permission="users:create">
        <Button>Create User</Button>
      </Can>

      <Can permission="users:read">
        <UserList />
      </Can>

      <Can
        permissions={['users:update', 'users:delete']}
        fallback={<p>You don't have permission to manage users.</p>}
      >
        <UserActions />
      </Can>
    </div>
  );
}
